          "prose": "<p>Nesta aula, a professora Paula Santana responde à pergunta central: **onde a voz começa?** Retomando a Aula 1, ela mostra que tudo se inicia no **cérebro**, cujas regiões específicas comandam a musculatura respiratória, a linguagem falada e cantada, a **percepção sonora** e a captação de **melodia e harmonia**. Esses comandos percorrem a **medula espinhal** até alcançar os músculos da respiração — por isso a aula a define como o verdadeiro ponto de partida da produção vocal.</p>\n<p>A partir daí, a aula se torna prática. O aluno é guiado a inspirar pelo nariz percebendo a expansão da **caixa torácica**, mantendo ombros e região clavicular relaxados. A professora apresenta a anatomia dessa estrutura — **pulmões**, **diafragma** e os **músculos intercostais** — e distingue dois grupos musculares complementares: os **intercostais externos** e o **diafragma**, que atuam na inspiração, e os **intercostais internos**, responsáveis pela expiração. Ambos precisam ser exercitados para que a voz tenha **equilíbrio**.</p>\n<p>Os exercícios propostos constroem a **sustentação** — palavra que a professora pede para \"guardar\", pois será retomada nas aulas de apoio vocal: sustentar o ar por 5 e 10 segundos sem desmontar a estrutura, realizar cinco inspirações curtas, soprar forte e continuamente, e emitir um **\"S\" contínuo** sem oscilação. Tudo isso desenvolve a **propriocepção**, a capacidade de sentir o que acontece dentro do corpo. A aula se encerra com o **caminho do ar** (nariz/boca → trato vocal → laringe → pulmões) e um vídeo que mostra o diafragma descendo na inspiração e relaxando na expiração.</p>",
          "proseRaw": "Nesta aula, a professora Paula Santana responde à pergunta central: **onde a voz começa?** Retomando a Aula 1, ela mostra que tudo se inicia no **cérebro**, cujas regiões específicas comandam a musculatura respiratória, a linguagem falada e cantada, a **percepção sonora** e a captação de **melodia e harmonia**. Esses comandos percorrem a **medula espinhal** até alcançar os músculos da respiração — por isso a aula a define como o verdadeiro ponto de partida da produção vocal.\n\nA partir daí, a aula se torna prática. O aluno é guiado a inspirar pelo nariz percebendo a expansão da **caixa torácica**, mantendo ombros e região clavicular relaxados. A professora apresenta a anatomia dessa estrutura — **pulmões**, **diafragma** e os **músculos intercostais** — e distingue dois grupos musculares complementares: os **intercostais externos** e o **diafragma**, que atuam na inspiração, e os **intercostais internos**, responsáveis pela expiração. Ambos precisam ser exercitados para que a voz tenha **equilíbrio**.\n\nOs exercícios propostos constroem a **sustentação** — palavra que a professora pede para \"guardar\", pois será retomada nas aulas de apoio vocal: sustentar o ar por 5 e 10 segundos sem desmontar a estrutura, realizar cinco inspirações curtas, soprar forte e continuamente, e emitir um **\"S\" contínuo** sem oscilação. Tudo isso desenvolve a **propriocepção**, a capacidade de sentir o que acontece dentro do corpo. A aula se encerra com o **caminho do ar** (nariz/boca → trato vocal → laringe → pulmões) e um vídeo que mostra o diafragma descendo na inspiração e relaxando na expiração.",
          "notas": "- **Aula exige participação ativa:** oriente o aluno a pausar o vídeo e repetir cada exercício, especialmente o do \"S\" — a oscilação do som é o indicador de que a sustentação falhou.\n- **Ponte com o Módulo 2:** o conceito de *sustentação* aqui introduzido é pré-requisito direto para as aulas de **apoio/suporte vocal** (Aulas 7 e 8 do ciclo 2022).\n- **Erro comum a observar:** elevação dos ombros na inspiração — a professora enfatiza manter a região clavicular relaxada.\n- **Persistência:** a transcrição reforça que a dificuldade inicial é normal; a musculatura se tonifica com o treino regular.",
