          "prose": "<p>Nesta aula, a professora Paula Santana consolida a compreensão de **como a voz se forma**. Tudo começa nos **comandos cerebrais**, que acionam a estrutura de respiração: sem **fluxo de ar contínuo**, não há voz — por isso, *voz de qualidade exige respiração de qualidade*. O aluno é convidado a enxergar o **corpo inteiro como instrumento**, e não apenas a laringe.</p>\n<p>O percurso do ar é detalhado: entra pelas **narinas ou boca**, atravessa o **trato vocal**, passa pela laringe — cuja região das pregas vocais é chamada **região glótica** — e segue pela **traqueia** até os pulmões, onde ocorrem as **trocas gasosas**. Na inspiração, as pregas vocais **se abrem**; na fala e no canto, o ar que retorna entra em contato com a musculatura e a mucosa das pregas, promovendo **vibração** — é aí que nasce o som, na **fonte**.</p>\n<p>Mas som sozinho não é voz: é apenas ruído, sem palavras. O som gerado na laringe é **moldado pelo filtro** — os **articuladores** — que transformam vibração em texto falado ou cantado. Fonte e filtro atuam **em conjunto**, sustentados pela musculatura respiratória e pelo **diafragma**, responsável pelo equilíbrio do fluxo de ar e, consequentemente, pela afinação, colocação vocal e articulação.</p>\n<p>A aula termina com exercícios de percepção: com a mão na laringe, o aluno emite **S** (apenas passagem de ar, sem vibração) e depois **Z**, **V** e **J** (fonte ativada, com vibração), integrando conscientemente **musculatura respiratória e fonte do som**.</p>",
          "proseRaw": "Nesta aula, a professora Paula Santana consolida a compreensão de **como a voz se forma**. Tudo começa nos **comandos cerebrais**, que acionam a estrutura de respiração: sem **fluxo de ar contínuo**, não há voz — por isso, *voz de qualidade exige respiração de qualidade*. O aluno é convidado a enxergar o **corpo inteiro como instrumento**, e não apenas a laringe.\n\nO percurso do ar é detalhado: entra pelas **narinas ou boca**, atravessa o **trato vocal**, passa pela laringe — cuja região das pregas vocais é chamada **região glótica** — e segue pela **traqueia** até os pulmões, onde ocorrem as **trocas gasosas**. Na inspiração, as pregas vocais **se abrem**; na fala e no canto, o ar que retorna entra em contato com a musculatura e a mucosa das pregas, promovendo **vibração** — é aí que nasce o som, na **fonte**.\n\nMas som sozinho não é voz: é apenas ruído, sem palavras. O som gerado na laringe é **moldado pelo filtro** — os **articuladores** — que transformam vibração em texto falado ou cantado. Fonte e filtro atuam **em conjunto**, sustentados pela musculatura respiratória e pelo **diafragma**, responsável pelo equilíbrio do fluxo de ar e, consequentemente, pela afinação, colocação vocal e articulação.\n\nA aula termina com exercícios de percepção: com a mão na laringe, o aluno emite **S** (apenas passagem de ar, sem vibração) e depois **Z**, **V** e **J** (fonte ativada, com vibração), integrando conscientemente **musculatura respiratória e fonte do som**.",
