          "prose": "<p>Nesta aula, a professora Paula Santana aprofunda o que já foi apresentado sobre o **instrumento voz**, reunindo tudo sob um único conceito: o **sistema fonador**, o conjunto de estruturas do corpo que trabalham — sob comando do cérebro — para produzir tanto a **voz falada** quanto a **voz cantada**.</p>\n<p>O percurso segue três estações. Primeiro, a **parte respiratória**: pulmões, **diafragma**, musculatura **abdominal** e **intercostal** comprimem o ar e geram o fluxo que pressiona a **região glótica** — é essa pressão que faz as pregas vocais vibrarem. Segundo, a **parte laríngea**: a vibração produz apenas um **som primário**, um \"zumbido\", e não a voz completa; ali, toda a musculatura laríngea atua em conjunto, realizando quatro movimentos básicos nas pregas — **afastamento, aproximação, encurtamento e alongamento**. Terceiro, o **trato vocal como filtro**: a **faringe** (nasofaringe, orofaringe e laringofaringe) e os **articuladores** (lábios, língua, dentes, mandíbula e palato mole) moldam o zumbido em voz articulada, definindo o **timbre** — a identidade vocal única de cada pessoa, influenciada pelo tamanho da laringe, das pregas vocais e até da caixa torácica.</p>\n<p>A aula se fecha com o esquema-síntese que organiza todo o curso: **ar → vibração → filtragem**, ou seja, **respiração → som → articulação → voz completa**. A curiosidade sobre os imitadores ilustra bem o ponto: quem imita vozes o faz **manuseando conscientemente o trato vocal** para reproduzir o molde sonoro desejado.</p>",
          "proseRaw": "Nesta aula, a professora Paula Santana aprofunda o que já foi apresentado sobre o **instrumento voz**, reunindo tudo sob um único conceito: o **sistema fonador**, o conjunto de estruturas do corpo que trabalham — sob comando do cérebro — para produzir tanto a **voz falada** quanto a **voz cantada**.\n\nO percurso segue três estações. Primeiro, a **parte respiratória**: pulmões, **diafragma**, musculatura **abdominal** e **intercostal** comprimem o ar e geram o fluxo que pressiona a **região glótica** — é essa pressão que faz as pregas vocais vibrarem. Segundo, a **parte laríngea**: a vibração produz apenas um **som primário**, um \"zumbido\", e não a voz completa; ali, toda a musculatura laríngea atua em conjunto, realizando quatro movimentos básicos nas pregas — **afastamento, aproximação, encurtamento e alongamento**. Terceiro, o **trato vocal como filtro**: a **faringe** (nasofaringe, orofaringe e laringofaringe) e os **articuladores** (lábios, língua, dentes, mandíbula e palato mole) moldam o zumbido em voz articulada, definindo o **timbre** — a identidade vocal única de cada pessoa, influenciada pelo tamanho da laringe, das pregas vocais e até da caixa torácica.\n\nA aula se fecha com o esquema-síntese que organiza todo o curso: **ar → vibração → filtragem**, ou seja, **respiração → som → articulação → voz completa**. A curiosidade sobre os imitadores ilustra bem o ponto: quem imita vozes o faz **manuseando conscientemente o trato vocal** para reproduzir o molde sonoro desejado.",
          "notas": "- Aula **teórico-conceitual**, sem exercícios práticos; funciona como consolidação e aprofundamento das Aulas 1–3.\n- A instrutora avisa que os termos anatômicos serão retomados \"pacientemente\" — tranquilize o aluno: neste momento basta reconhecer as três partes e os quatro movimentos das pregas.\n- O esquema **ar → vibração → filtragem** é explicitamente apresentado como base para assuntos futuros (ressonância, registros, articulação) — vale pedir ao aluno que o redesenhe de memória como autoavaliação.\n- Conexão direta com o Módulo 3 do curso (três subsistemas), que revisita este conteúdo no ciclo 2024–2025.",
