          "prose": "<p>A laringe é apresentada como a **fonte do som** — é nela que estão os mecanismos musculares que dão origem à voz. Situada no **topo da traqueia**, bem no meio do trato respiratório, ela integra o que a instrutora chama de **centro do instrumento voz**: não apenas laringe ou pulmões isoladamente, mas todo o conjunto que vai das narinas e lábios até a estrutura pulmonar. Um primeiro exercício de consciência corporal é simples: **colocar a mão no pescoço ao falar** e perceber a vibração produzida nessa região.</p>\n<p>A estrutura da laringe é formada por **cartilagens** ligadas entre si por membranas ligamentosas. A **tireóidea** é a maior delas e funciona como uma espécie de \"escudo\" frontal — nos homens, é o que aparece como **pomo de adão**. A **epiglote** atua como tampa de proteção: durante a **deglutação**, ela fecha a entrada da laringe para que nenhum alimento desça pela via respiratória.</p>\n<p>Sobre os músculos, a aula organiza dois grandes grupos. Os **extrínsecos** ficam por fora da laringe e a movimentam como um todo: os **supra-hióideos** a **elevam** (movimento perceptível, por exemplo, em notas agudas) e os **infra-hióideos** a **abaixam**. Aqui entra um alerta prático: o **trapézio**, embora não se ligue diretamente à laringe, pode comprometer a voz quando tensionado — daí a importância de **alongar e massagear o pescoço no aquecimento**. Os **intrínsecos**, com origem e inserção dentro da própria laringe, agem diretamente sobre as **pregas vocais**: os **abdutores** as **abrem** (mnemônico: \"ab de abrir\" — é o que acontece na inspiração), os **adutores** as **fecham** (na fonação e também como proteção rápida contra engasgos), além de **tensores** e **relaxadores** que ajustam sua tensão. O **cricoaritenóideo lateral**, responsável por abrir a glote para a entrada de ar, é conhecido como \"**músculo da vida**\".</p>",
          "proseRaw": "A laringe é apresentada como a **fonte do som** — é nela que estão os mecanismos musculares que dão origem à voz. Situada no **topo da traqueia**, bem no meio do trato respiratório, ela integra o que a instrutora chama de **centro do instrumento voz**: não apenas laringe ou pulmões isoladamente, mas todo o conjunto que vai das narinas e lábios até a estrutura pulmonar. Um primeiro exercício de consciência corporal é simples: **colocar a mão no pescoço ao falar** e perceber a vibração produzida nessa região.\n\nA estrutura da laringe é formada por **cartilagens** ligadas entre si por membranas ligamentosas. A **tireóidea** é a maior delas e funciona como uma espécie de \"escudo\" frontal — nos homens, é o que aparece como **pomo de adão**. A **epiglote** atua como tampa de proteção: durante a **deglutação**, ela fecha a entrada da laringe para que nenhum alimento desça pela via respiratória.\n\nSobre os músculos, a aula organiza dois grandes grupos. Os **extrínsecos** ficam por fora da laringe e a movimentam como um todo: os **supra-hióideos** a **elevam** (movimento perceptível, por exemplo, em notas agudas) e os **infra-hióideos** a **abaixam**. Aqui entra um alerta prático: o **trapézio**, embora não se ligue diretamente à laringe, pode comprometer a voz quando tensionado — daí a importância de **alongar e massagear o pescoço no aquecimento**. Os **intrínsecos**, com origem e inserção dentro da própria laringe, agem diretamente sobre as **pregas vocais**: os **abdutores** as **abrem** (mnemônico: \"ab de abrir\" — é o que acontece na inspiração), os **adutores** as **fecham** (na fonação e também como proteção rápida contra engasgos), além de **tensores** e **relaxadores** que ajustam sua tensão. O **cricoaritenóideo lateral**, responsável por abrir a glote para a entrada de ar, é conhecido como \"**músculo da vida**\".",
          "notas": "- A instrutora **desdramatiza os nomes difíceis**: assim como o pianista conhece as partes do piano para entender como o som nasce, o cantor deve conhecer as partes do seu instrumento — sem exigência de decorar cada termo.\n- Dois **testes práticos imediatos** propostos: mão no pescoço para sentir a vibração; inspirar pelo nariz percebendo a abertura das pregas vocais.\n- Reforça a **continuidade do curso**: glote e traqueia já foram vistas em aulas anteriores.",
