          "prose": "<p>Nesta aula, a professora Paula Santana consolida o **modelo completo da produção do som vocal**, reunindo em uma única visão tudo o que foi estudado separadamente nas aulas anteriores. O ponto de partida é a **cinta muscular respiratória** — diafragma, musculatura intercostal e abdominal — que, na expiração, fornece a **pressão de ar** direcionada à região glótica. É o contato desse ar com as **pregas vocais** que inicia o **ciclo vibratório** e gera o primeiro som.</p>\n<p>Um conceito central da aula é a distinção entre **som e voz**: na laringe temos \"basicamente som\"; a **voz completa** só existe depois que esse som atravessa o **trato vocal**, onde as cavidades nasal, oral e laringofaríngea funcionam como **filtro**. É nesse percurso que a configuração única de cada corpo gera o **timbre individual**, e que o movimento dos articuladores — a **articulação** — molda vogais e consoantes.</p>\n<p>A aula enfatiza ainda que **nada funciona isolado**: pelo **reflexo mioelástico**, cada músculo influencia o vizinho, de modo que deficiências na fonte obrigam o filtro a **compensar**, gerando desequilíbrio e incoordenação vocal. Por isso, a instrutora alerta: **rouquidão e incômodos frequentes não são normais** — podem indicar tensão excessiva, excesso de pressão de ar ou uma emissão frouxa, sem apoio. A estabilidade do som depende diretamente da **estabilidade do apoio respiratório**.</p>",
          "proseRaw": "Nesta aula, a professora Paula Santana consolida o **modelo completo da produção do som vocal**, reunindo em uma única visão tudo o que foi estudado separadamente nas aulas anteriores. O ponto de partida é a **cinta muscular respiratória** — diafragma, musculatura intercostal e abdominal — que, na expiração, fornece a **pressão de ar** direcionada à região glótica. É o contato desse ar com as **pregas vocais** que inicia o **ciclo vibratório** e gera o primeiro som.\n\nUm conceito central da aula é a distinção entre **som e voz**: na laringe temos \"basicamente som\"; a **voz completa** só existe depois que esse som atravessa o **trato vocal**, onde as cavidades nasal, oral e laringofaríngea funcionam como **filtro**. É nesse percurso que a configuração única de cada corpo gera o **timbre individual**, e que o movimento dos articuladores — a **articulação** — molda vogais e consoantes.\n\nA aula enfatiza ainda que **nada funciona isolado**: pelo **reflexo mioelástico**, cada músculo influencia o vizinho, de modo que deficiências na fonte obrigam o filtro a **compensar**, gerando desequilíbrio e incoordenação vocal. Por isso, a instrutora alerta: **rouquidão e incômodos frequentes não são normais** — podem indicar tensão excessiva, excesso de pressão de ar ou uma emissão frouxa, sem apoio. A estabilidade do som depende diretamente da **estabilidade do apoio respiratório**.",
          "notas": "- Aula de **síntese e consolidação**: ideal para revisão após as aulas de respiração, sistema fonador e laringe; funciona como \"fecho\" do Módulo 1.\n- Conecta-se diretamente ao Módulo 3 (energia–fonte–filtro), que aprofunda o mesmo modelo no ciclo 2024–2025 — útil como revisão prévia.\n- Os termos **voz de peito, cabeça, falsete e mix** são apenas citados aqui; o estudo detalhado ocorre no Módulo 4 (registros e modos de fonação). Evitar antecipar exercícios.\n- O alerta sobre saúde vocal (t=615) é bom momento para reforçar a cultura de autocuidado do cantor de louvor.",
