          "prose": "<p>A aula apresenta o mapa conceitual que organiza todo o curso: a voz nasce de **três pilares encadeados**. O primeiro é a **respiração** — não apenas pulmões e **diafragma**, mas todo o aparato de músculos respiratórios (**intercostais** externa e interna, **reto abdominal**, **transverso**, **oblíquos**), responsável pela sustentação do fluxo de ar. A instrutora antecipa o termo **apoio**, que será aprofundado nas aulas seguintes.</p>\n<p>O segundo pilar é a **fonação**: o ar expirado encontra as **pregas vocais** fechadas na **laringe**, gera **resistência** na região **subglótica** e produz **vibração** — fenômeno que o aluno pode sentir com a mão no pescoço. Ressalva importante: a fonação **ainda não é a voz completa**, apenas a fonte do som; por ser região delicada, tensões inadequadas podem gerar desconforto e problemas futuros.</p>\n<p>O terceiro pilar é o **filtro**: o **trato vocal** (da laringe à boca e ao nariz, com regiões **oral**, **nasal** e **faríngea**) molda as **ondas sonoras/harmônicos** por meio dos **articuladores** — língua, lábios, mandíbula, dentes, **palato mole**, faringe e laringe. É nas **cavidades de ressonância** que o som é aperfeiçoado e surge o **timbre**, a identidade vocal que torna cada voz única e reconhecível.</p>",
          "proseRaw": "A aula apresenta o mapa conceitual que organiza todo o curso: a voz nasce de **três pilares encadeados**. O primeiro é a **respiração** — não apenas pulmões e **diafragma**, mas todo o aparato de músculos respiratórios (**intercostais** externa e interna, **reto abdominal**, **transverso**, **oblíquos**), responsável pela sustentação do fluxo de ar. A instrutora antecipa o termo **apoio**, que será aprofundado nas aulas seguintes.\n\nO segundo pilar é a **fonação**: o ar expirado encontra as **pregas vocais** fechadas na **laringe**, gera **resistência** na região **subglótica** e produz **vibração** — fenômeno que o aluno pode sentir com a mão no pescoço. Ressalva importante: a fonação **ainda não é a voz completa**, apenas a fonte do som; por ser região delicada, tensões inadequadas podem gerar desconforto e problemas futuros.\n\nO terceiro pilar é o **filtro**: o **trato vocal** (da laringe à boca e ao nariz, com regiões **oral**, **nasal** e **faríngea**) molda as **ondas sonoras/harmônicos** por meio dos **articuladores** — língua, lábios, mandíbula, dentes, **palato mole**, faringe e laringe. É nas **cavidades de ressonância** que o som é aperfeiçoado e surge o **timbre**, a identidade vocal que torna cada voz única e reconhecível.",
          "notas": "- A instrutora orienta o aluno a manter um **caderno de termos** (*ressonância*, *apoio*), prometendo retomá-los — reforce essa prática como estratégia de estudo contínuo.\n- A aula é **conceitual** (sem exercícios práticos); os vocalizes respiratórios vêm na aula seguinte (Aula 5). Usar esta aula como \"mapa\" antes da prática.\n- Experiência sensorial sugerida em vídeo: mão no pescoço durante a fala para perceber a **vibração laríngea** — boa atividade de fixação em casa.",
