          "prose": "<p>Esta é a primeira **aula prática** do curso: nada de teoria nova — o objetivo é *treinar* o pilar da respiração estudado na Aula 4. A instrutora parte da anatomia (pulmões, caixa torácica, **diafragma**, intercostais, abdômen) para justificar a **respiração costodiafragmática abdominal** como a mais completa para o canto, já que quanto mais musculatura participa, maior a **sustentação** da voz. Um ponto de atenção: as **clavículas não devem se mover** — nada de respiração alta e tensa.</p>\n<p>O coração da aula é o ciclo em três tempos: **ativação** (inspirar contraindo a musculatura), **fonação** (emitir o som mantendo a estrutura acionada — é isso que chamamos de **apoio**) e **relaxamento** (só ao final). Os exercícios progridem em dificuldade: S longo de 5 a 10 segundos, emissão com **Z** em notas musicais, inspirações fracionadas para o diafragma (\"contrair e ficar\") e S seriado com contrações abdominais. A aluna também aprende duas estratégias de inspiração: a **nasal, calma**, e a **nasobucal rápida** (comparada a um susto), necessária em frases de hinos com pouco espaço para respirar.</p>\n<p>**Nota de segurança:** a instrutora alerta que exercícios respiratórios intensos aumentam a oxigenação cerebral e podem causar **leve tonteira** (especialmente em quem tem labirintite). Tudo deve ser feito com calma e **autopercepção** corporal.</p>",
          "proseRaw": "Esta é a primeira **aula prática** do curso: nada de teoria nova — o objetivo é *treinar* o pilar da respiração estudado na Aula 4. A instrutora parte da anatomia (pulmões, caixa torácica, **diafragma**, intercostais, abdômen) para justificar a **respiração costodiafragmática abdominal** como a mais completa para o canto, já que quanto mais musculatura participa, maior a **sustentação** da voz. Um ponto de atenção: as **clavículas não devem se mover** — nada de respiração alta e tensa.\n\nO coração da aula é o ciclo em três tempos: **ativação** (inspirar contraindo a musculatura), **fonação** (emitir o som mantendo a estrutura acionada — é isso que chamamos de **apoio**) e **relaxamento** (só ao final). Os exercícios progridem em dificuldade: S longo de 5 a 10 segundos, emissão com **Z** em notas musicais, inspirações fracionadas para o diafragma (\"contrair e ficar\") e S seriado com contrações abdominais. A aluna também aprende duas estratégias de inspiração: a **nasal, calma**, e a **nasobucal rápida** (comparada a um susto), necessária em frases de hinos com pouco espaço para respirar.\n\n**Nota de segurança:** a instrutora alerta que exercícios respiratórios intensos aumentam a oxigenação cerebral e podem causar **leve tonteira** (especialmente em quem tem labirintite). Tudo deve ser feito com calma e **autopercepção** corporal.",
