          "prose": "<p>Esta é a aula que **transfere o apoio da teoria para o corpo**. A instrutora sintetiza o conceito em três verbos — **inspirar, ativar e manter** — e deixa claro que a internalização exige **treino diário**, com tempos diferentes para cada aluno. A distinção proposta é precisa: *treino* é o momento reservado para testar possibilidades; *prática* é a aplicação na realidade do louvor, na igreja ou em casa. Há ainda a sugestão de reunir o grupo de louvor para assistir e treinar junto, aproveitando a observação mútua.</p>\n<p>O ponto técnico central é a **expansão lateral** da estrutura respiratória. Elevar o peito e os ombros gera tensão clavicular e cervical — região onde estão **musculaturas essenciais à produção vocal** —, enquanto encolher a barriga de forma rígida pode **travar a laringe e endurecer a voz**. A resposta é o **equilíbrio muscular**: estrutura ativa, porém sem contração exagerada. A progressão de sustentação (5 → 10 → 15 segundos) constrói essa resistência, sempre com **postura alinhada** (ombros equilibrados, coluna reta, pescoço relaxado).</p>\n<p>Na sequência, o apoio ganha voz. A **inspiração fracionada em três tempos** ensina a administrar a abertura da musculatura; o **trêmulo de lábios ou língua** introduz os **exercícios de trato vocal semiocluído (TVS)**, nos quais o fluxo de ar encontra resistência parcial — trabalhando ao mesmo tempo fluxo apoiado e **articuladores**. O vocalize com vogais, pedido com **articulação exagerada**, mostra que os articuladores **moldam e projetam o som**: sem apoio e sem ajuste do trato vocal, \"o som fica preso lá dentro\". A aula fecha com um exercício de **salto de intervalo (Dó–Sol)** na vogal **U**, cujo objetivo é manter a **leveza da voz** na passagem entre notas distantes — tudo sustentado pelo apoio.</p>\n<p>> **Nota didática:** reforce aos alunos que \"relaxar\" a estrutura só acontece **depois** de encerrada a frase musical — nunca durante o apoio. Esse é um erro comum apontado pela própria instrutora.</p>",
          "proseRaw": "Esta é a aula que **transfere o apoio da teoria para o corpo**. A instrutora sintetiza o conceito em três verbos — **inspirar, ativar e manter** — e deixa claro que a internalização exige **treino diário**, com tempos diferentes para cada aluno. A distinção proposta é precisa: *treino* é o momento reservado para testar possibilidades; *prática* é a aplicação na realidade do louvor, na igreja ou em casa. Há ainda a sugestão de reunir o grupo de louvor para assistir e treinar junto, aproveitando a observação mútua.\n\nO ponto técnico central é a **expansão lateral** da estrutura respiratória. Elevar o peito e os ombros gera tensão clavicular e cervical — região onde estão **musculaturas essenciais à produção vocal** —, enquanto encolher a barriga de forma rígida pode **travar a laringe e endurecer a voz**. A resposta é o **equilíbrio muscular**: estrutura ativa, porém sem contração exagerada. A progressão de sustentação (5 → 10 → 15 segundos) constrói essa resistência, sempre com **postura alinhada** (ombros equilibrados, coluna reta, pescoço relaxado).\n\nNa sequência, o apoio ganha voz. A **inspiração fracionada em três tempos** ensina a administrar a abertura da musculatura; o **trêmulo de lábios ou língua** introduz os **exercícios de trato vocal semiocluído (TVS)**, nos quais o fluxo de ar encontra resistência parcial — trabalhando ao mesmo tempo fluxo apoiado e **articuladores**. O vocalize com vogais, pedido com **articulação exagerada**, mostra que os articuladores **moldam e projetam o som**: sem apoio e sem ajuste do trato vocal, \"o som fica preso lá dentro\". A aula fecha com um exercício de **salto de intervalo (Dó–Sol)** na vogal **U**, cujo objetivo é manter a **leveza da voz** na passagem entre notas distantes — tudo sustentado pelo apoio.\n\n> **Nota didática:** reforce aos alunos que \"relaxar\" a estrutura só acontece **depois** de encerrada a frase musical — nunca durante o apoio. Esse é um erro comum apontado pela própria instrutora.",
