          "prose": "<p>Nesta aula, a professora Paula Santana introduz a **colocação vocal** sob a perspectiva do **início e do término do som**. O conceito central é o **equilíbrio muscular**: como a voz é produzida pelo corpo, a forma como iniciamos e encerramos o som tem impacto direto na **saúde vocal** e na qualidade da emissão.</p>\n<p>Um ponto fundamental da fisiologia vocal é destacado: a **laringe e sua musculatura se posicionam antes mesmo de o som existir**. Por isso, iniciar a voz de forma consciente evita **tensão, apertamento e constrição**, permitindo que a movimentação laríngea aconteça de modo equilibrado.</p>\n<p>O treino é organizado em uma sequência de três etapas cumulativas: **(1) respirar e apoiar** — inspirar com expansão da caixa torácica, ativando diafragma, musculatura intercostal e abdominal; **(2) espaços e formas** — posicionar as cavidades de ressonância e as formas das **vogais** do texto a ser cantado; **(3) som da voz** — liberar a emissão. Essa coordenação prévia recebe o nome de **sintonia pré-fonatória**: a harmonia dos movimentos musculares *antes* da fonação.</p>\n<p>A aula reforça o caráter **cumulativo** do curso: o conteúdo depende diretamente das aulas de **apoio vocal** e do **sistema fonador**. Quem inicia com qualidade e mantém a sustentação do apoio colhe automaticamente um **término equilibrado** — a frase termina com qualidade de som, e o reabastecimento de ar (inspirações curtas, porém eficazes) mantém o suporte para a frase seguinte.</p>",
          "proseRaw": "Nesta aula, a professora Paula Santana introduz a **colocação vocal** sob a perspectiva do **início e do término do som**. O conceito central é o **equilíbrio muscular**: como a voz é produzida pelo corpo, a forma como iniciamos e encerramos o som tem impacto direto na **saúde vocal** e na qualidade da emissão.\n\nUm ponto fundamental da fisiologia vocal é destacado: a **laringe e sua musculatura se posicionam antes mesmo de o som existir**. Por isso, iniciar a voz de forma consciente evita **tensão, apertamento e constrição**, permitindo que a movimentação laríngea aconteça de modo equilibrado.\n\nO treino é organizado em uma sequência de três etapas cumulativas: **(1) respirar e apoiar** — inspirar com expansão da caixa torácica, ativando diafragma, musculatura intercostal e abdominal; **(2) espaços e formas** — posicionar as cavidades de ressonância e as formas das **vogais** do texto a ser cantado; **(3) som da voz** — liberar a emissão. Essa coordenação prévia recebe o nome de **sintonia pré-fonatória**: a harmonia dos movimentos musculares *antes* da fonação.\n\nA aula reforça o caráter **cumulativo** do curso: o conteúdo depende diretamente das aulas de **apoio vocal** e do **sistema fonador**. Quem inicia com qualidade e mantém a sustentação do apoio colhe automaticamente um **término equilibrado** — a frase termina com qualidade de som, e o reabastecimento de ar (inspirações curtas, porém eficazes) mantém o suporte para a frase seguinte.",
          "notas": "- **Pré-requisitos explícitos:** a aula pressupõe as aulas de apoio/suporte (Aulas 7–8) e de sistema fonador (Aula 9). Reforce esses vínculos ao estudante antes de iniciar.\n- **Sugestão prática da própria instrutora** ([t=298](https://www.youtube.com/watch?v=obE_0NBAFdk&t=298)): gravar o treino com o celular para se ouvir \"de fora da própria caixa\" — incentivar esse hábito como rotina de estudo.\n- Distinguir bem **treino vocal** (momento de experimentar, repetir e se conhecer) de **prática vocal** (aplicação no canto).\n- A transcrição apresenta erros de reconhecimento (\"laranja\" = **laringe**; \"sinfonatória\" = **pré-fonatória**); usar os termos corretos no material escrito.",
          "exercicios": "Prática vocal e exercícios específicos ministrados pela Prof.ª Paula Santana para o Módulo 2."
