          "prose": "<p>Esta aula transforma em **treino prático** o princípio estudado na aula anterior: antes de qualquer som, a **respiração** prepara a estrutura muscular da voz. A instrutora conduz uma sequência de exercícios de **fortalecimento diafragmático** em que o aluno aprende a \"tomar o controle\" da musculatura: inspirações e expirações **fracionadas em impulsos** (2, 3, 4 ou mais), com **retenção** mantendo o diafragma ativo. A progressão de dificuldade funciona como \"posição de superação\" que desenvolve **tônus, consistência e resistência muscular** — sempre sem elevar os ombros e sem tensionar a garganta.</p>\n<p>Um marco conceitual importante da aula é a distinção entre **aquecimento** e **vocalize**: o aquecimento trabalha a **musculatura** em si; o vocalize trabalha a **sonoridade**. Por isso os exercícios respiratórios vêm *antes* de pensar em \"som bonito\". Na sequência, os impulsos ganham vogais (A, I, U), introduzindo as noções de **staccato** e **legato** — com o alerta de que as pausas entre notas curtas são **pausas de silêncio, não de respiração** — e mostrando que **cada vogal tem sua posição no trato vocal** (o U, por exemplo, exige projeção dos lábios).</p>\n<p>A aula se encerra aplicando tudo ao hino *\"Nesta Hora de Clamor\"*: antes da melodia, a frase inicial é lida em seu **ritmo e divisão silábica**, reforçando que **início e término do som** precisam ter qualidade — e que ambos dependem da estrutura respiratória preparada.</p>",
          "proseRaw": "Esta aula transforma em **treino prático** o princípio estudado na aula anterior: antes de qualquer som, a **respiração** prepara a estrutura muscular da voz. A instrutora conduz uma sequência de exercícios de **fortalecimento diafragmático** em que o aluno aprende a \"tomar o controle\" da musculatura: inspirações e expirações **fracionadas em impulsos** (2, 3, 4 ou mais), com **retenção** mantendo o diafragma ativo. A progressão de dificuldade funciona como \"posição de superação\" que desenvolve **tônus, consistência e resistência muscular** — sempre sem elevar os ombros e sem tensionar a garganta.\n\nUm marco conceitual importante da aula é a distinção entre **aquecimento** e **vocalize**: o aquecimento trabalha a **musculatura** em si; o vocalize trabalha a **sonoridade**. Por isso os exercícios respiratórios vêm *antes* de pensar em \"som bonito\". Na sequência, os impulsos ganham vogais (A, I, U), introduzindo as noções de **staccato** e **legato** — com o alerta de que as pausas entre notas curtas são **pausas de silêncio, não de respiração** — e mostrando que **cada vogal tem sua posição no trato vocal** (o U, por exemplo, exige projeção dos lábios).\n\nA aula se encerra aplicando tudo ao hino *\"Nesta Hora de Clamor\"*: antes da melodia, a frase inicial é lida em seu **ritmo e divisão silábica**, reforçando que **início e término do som** precisam ter qualidade — e que ambos dependem da estrutura respiratória preparada.",
          "notas": "- A participação da **Jordânia** permite ao aluno *ver* a movimentação intercostal em outro corpo — recurso útil para quem treina sozinho em frente ao espelho.\n- A progressão 2→3→4 (→5→6) impulsos deve ser respeitada: cada pulso fica \"mais curtinho\", exigindo expansão **sem tensão** em costelas, clavícula e pescoço.\n- Reforçar com o aluno o critério de **autopercepção**: dor, aperto na garganta ou elevação de ombros indicam execução inadequada.\n- A aula pressupõe os conteúdos das Aulas 4, 5, 7, 8 e 10 (pilares, respiração costodiafragmática, apoio e colocação vocal).",
          "exercicios": "Prática vocal e exercícios específicos ministrados pela Prof.ª Paula Santana para o Módulo 2."
