          "prose": "<p>O canto é uma **atividade física** e, como tal, exige um tipo específico de respiração — e uma **postura corporal** que a permita. A professora Paula inicia pela base: **ombros sutilmente girados para trás** e **coluna ereta**, pois ombros projetados à frente limitam a ação dos **intercostais** e do **diafragma**. A musculatura **abdominal** participa, mas apenas como **suporte auxiliar**, nunca como protagonista.</p>\n<p>Em seguida, a aula percorre as **três regiões respiratórias**. A **região alta** (clavícula e pescoço) aciona musculaturas acessórias ligadas à laringe e gera **tensão** — deve ser evitada. A **região baixa** (abdominal-pélvica), quando usada como principal, pode gerar tensão excessiva na **região glótica**. Resta a **região média** — diafragma e intercostais —, o \"espacinho do corpo\" que o cantor deve sempre movimentar: na inspiração, os intercostais se abrem e o diafragma se contrai, sustentando um **fluxo de ar equilibrado**. É por isso que a **voz cantada** difere da **voz falada**, que tende a ser mais abdominal.</p>\n<p>A parte prática propõe o exercício da **sucção sutil** — imaginar um espaguete fininho ou um canudinho —, que provoca o reflexo de abertura da região média sem tensão no pescoço, seguido de emissão em **S** e em **X**, sempre sustentando a estrutura diafragmática-intercostal. O exercício reproduz as **três etapas** presentes em qualquer hino: inspirar, sustentar cantando e expirar totalmente. A professora faz um alerta essencial de **saúde vocal**: **contração** (ativação muscular natural e intensa) não é **tensão** — esta nunca é bem-vinda, pois se transfere às pregas vocais; ao percebê-la, pare, respire e retome.</p>\n<p>Por fim, a aula introduz a **pressão subglótica**: o ar sustentado gera pressão abaixo das pregas vocais, e o nível dessa pressão define como elas respondem nas regiões **grave, média e aguda**. Nem excesso, nem frouxidão — as pregas vocais são um \"parzinho de músculo\" pequeno e delicado, que pede movimento **natural, sutil e consciente**.</p>\n<p>---</p>",
          "proseRaw": "O canto é uma **atividade física** e, como tal, exige um tipo específico de respiração — e uma **postura corporal** que a permita. A professora Paula inicia pela base: **ombros sutilmente girados para trás** e **coluna ereta**, pois ombros projetados à frente limitam a ação dos **intercostais** e do **diafragma**. A musculatura **abdominal** participa, mas apenas como **suporte auxiliar**, nunca como protagonista.\n\nEm seguida, a aula percorre as **três regiões respiratórias**. A **região alta** (clavícula e pescoço) aciona musculaturas acessórias ligadas à laringe e gera **tensão** — deve ser evitada. A **região baixa** (abdominal-pélvica), quando usada como principal, pode gerar tensão excessiva na **região glótica**. Resta a **região média** — diafragma e intercostais —, o \"espacinho do corpo\" que o cantor deve sempre movimentar: na inspiração, os intercostais se abrem e o diafragma se contrai, sustentando um **fluxo de ar equilibrado**. É por isso que a **voz cantada** difere da **voz falada**, que tende a ser mais abdominal.\n\nA parte prática propõe o exercício da **sucção sutil** — imaginar um espaguete fininho ou um canudinho —, que provoca o reflexo de abertura da região média sem tensão no pescoço, seguido de emissão em **S** e em **X**, sempre sustentando a estrutura diafragmática-intercostal. O exercício reproduz as **três etapas** presentes em qualquer hino: inspirar, sustentar cantando e expirar totalmente. A professora faz um alerta essencial de **saúde vocal**: **contração** (ativação muscular natural e intensa) não é **tensão** — esta nunca é bem-vinda, pois se transfere às pregas vocais; ao percebê-la, pare, respire e retome.\n\nPor fim, a aula introduz a **pressão subglótica**: o ar sustentado gera pressão abaixo das pregas vocais, e o nível dessa pressão define como elas respondem nas regiões **grave, média e aguda**. Nem excesso, nem frouxidão — as pregas vocais são um \"parzinho de músculo\" pequeno e delicado, que pede movimento **natural, sutil e consciente**.\n\n---",
          "notas": "- **Pré-requisito direto:** esta aula pressupõe o conceito de **apoio vocal** (Aulas 7–8 de 2022, `Ica7I2xsZjc` e `njcHYUvAMng`), recapitulado em [t=527](https://www.youtube.com/watch?v=eKDFAAsXqeQ&t=527). Reforce o link com o subsistema de produção/suporte de ar (Módulo 3, `FYJdTQm0ZqY`), gravado uma semana antes.\n- **Treino gradual:** a instrutora enfatiza que musculaturas respondem por **estímulo repetido** — incentive o aluno a refazer o exercício em sessões curtas, sem buscar duração máxima logo de início.\n- **Critério de segurança:** transforme o alerta \"sentiu tensão → pare\" em regra de estudo; é o primeiro embrião do tema **modos de fonação** (Módulo 4).\n- **Aplicação no louvor:** as três etapas (inspiração → sustentação → expiração total) devem ser mapeadas pelo aluno nas frases e pausas de um hino do repertório da igreja.",
          "exercicios": "Prática vocal e exercícios específicos ministrados pela Prof.ª Paula Santana para o Módulo 2."
