          "prose": "<p>A aula parte de uma pergunta direta: *você tem seu fluxo de ar controlado na hora de cantar?* Para responder, a instrutora recapitula a **anatomia da respiração**: o suporte de ar nasce da **musculatura inspiratória** — os **intercostais externos** elevam as costelas no chamado **movimento de alça de balde**, enquanto o **diafragma** desce e se expande, montando a estrutura de **apoio**. O ponto central é que o controle do fluxo não vem da *quantidade* de ar, mas da *qualidade* da abertura e do equilíbrio dessas estruturas — sem respiração alta nem tensionamento.</p>\n<p>O treino progride em etapas: primeiro a **ativação do apoio** com retenções de 5 a 10 segundos (sem som); depois o **S longo**, que exige fluxo **contínuo, equilibrado e sem oscilações** — oscilação no ar revela falha na sustentação ou na musculatura da prega vocal. Um alerta importante: o aluno deve **manter a estrutura de apoio ativa até o último instante** da emissão, desmontando-a só depois; relaxar antes do fim compromete o fluxo e o som.</p>\n<p>Em seguida, o exercício ganha som: o **S transforma-se em Z** ao adicionar vibração das pregas vocais (percebida com a mão no pescoço), e o mesmo princípio vale para o par **F/V** (dentes superiores + lábio inferior). A instrutora enfatiza a **estrutura interna do trato vocal**: na inspiração, o **palato mole se ergue** e a **laringe desce**, criando espaço para que o som não fique tenso ou constrito, mesmo com o ponto articulatório obstruindo parcialmente o ar.</p>\n<p>Por fim, o fluxo controlado é aplicado em **glissandos grave–agudo** e **oitavas \"preguiçosas\"** (portamento lento), que colocam a prega vocal em dinâmica de **encurtamento e alongamento** — sempre com apoio constante. A aula culmina na **reativação do apoio sem soltar todo o ar**, reproduzindo as pequenas retomadas de fôlego que acontecem entre as frases de um hino. Como lembra a professora: o corpo é um instrumento vivo, e **canto é repetição** — esse treino é para todos os cantores, sempre.</p>",
          "proseRaw": "A aula parte de uma pergunta direta: *você tem seu fluxo de ar controlado na hora de cantar?* Para responder, a instrutora recapitula a **anatomia da respiração**: o suporte de ar nasce da **musculatura inspiratória** — os **intercostais externos** elevam as costelas no chamado **movimento de alça de balde**, enquanto o **diafragma** desce e se expande, montando a estrutura de **apoio**. O ponto central é que o controle do fluxo não vem da *quantidade* de ar, mas da *qualidade* da abertura e do equilíbrio dessas estruturas — sem respiração alta nem tensionamento.\n\nO treino progride em etapas: primeiro a **ativação do apoio** com retenções de 5 a 10 segundos (sem som); depois o **S longo**, que exige fluxo **contínuo, equilibrado e sem oscilações** — oscilação no ar revela falha na sustentação ou na musculatura da prega vocal. Um alerta importante: o aluno deve **manter a estrutura de apoio ativa até o último instante** da emissão, desmontando-a só depois; relaxar antes do fim compromete o fluxo e o som.\n\nEm seguida, o exercício ganha som: o **S transforma-se em Z** ao adicionar vibração das pregas vocais (percebida com a mão no pescoço), e o mesmo princípio vale para o par **F/V** (dentes superiores + lábio inferior). A instrutora enfatiza a **estrutura interna do trato vocal**: na inspiração, o **palato mole se ergue** e a **laringe desce**, criando espaço para que o som não fique tenso ou constrito, mesmo com o ponto articulatório obstruindo parcialmente o ar.\n\nPor fim, o fluxo controlado é aplicado em **glissandos grave–agudo** e **oitavas \"preguiçosas\"** (portamento lento), que colocam a prega vocal em dinâmica de **encurtamento e alongamento** — sempre com apoio constante. A aula culmina na **reativação do apoio sem soltar todo o ar**, reproduzindo as pequenas retomadas de fôlego que acontecem entre as frases de um hino. Como lembra a professora: o corpo é um instrumento vivo, e **canto é repetição** — esse treino é para todos os cantores, sempre.",
          "notas": "- Aula **prática e progressiva**: cada exercício parte do anterior (ar sem som → S → Z/V → glissando → oitava → reativação). Oriente o aluno a não pular etapas.\n- Reforça conceitos das aulas de **apoio e suporte** (Módulo 2) e prepara para o trabalho de **consoantes fricativas** (Módulo 6) e **registros** (Módulo 4), ao introduzir encurtamento/alongamento da prega vocal.\n- Ponto de atenção recorrente: fluxo oscilante pode indicar problema de sustentação *ou* questão muscular na prega vocal — bom gancho para auto-observação do aluno.",
