          "prose": "<p>Esta aula abre o novo ciclo do programa com o mapa completo da **produção vocal**. A instrutora apresenta os **três subsistemas** que trabalham em conjunto: primeiro, o subsistema de **produção de ar** — o ar é a **energia da voz** (\"sem ar, não temos som, não temos voz\"); segundo, o subsistema de **produção de som**, que acontece nas **pregas vocais**, na **laringe** — e aqui ainda temos apenas *som*, não voz; por fim, o trabalho do **trato vocal**, do **trato nasal** e dos **articuladores**, que amplificam e modificam o som, resultando na **voz completa**.</p>\n<p>Na sequência, a aula mergulha na fisiologia da **inspiração** por meio de uma pergunta disparadora: o ar entra primeiro, ou a musculatura se contrai primeiro? A resposta mostra que a **musculatura inspiratória** (intercostais externos e diafragma) recebe **estímulos neurológicos**, contrai-se, amplia a **caixa torácica** e só então o ar é puxado para dentro dos pulmões. O movimento das costelas é comparado à **alça de balde** — para fora e para cima — e o **diafragma** desce e expande em toda a sua porção, não apenas na frente do corpo.</p>\n<p>Por fim, destaca-se o diafragma como o **músculo mais importante da respiração** e também **músculo postural**: enquanto está ativo, há equilíbrio e sustentação do fluxo de ar; se relaxa, a base da produção vocal \"desmonta\". Como o canto exige muito mais da musculatura do que a fala, a **técnica vocal** existe para refinar esse processo.</p>",
          "proseRaw": "Esta aula abre o novo ciclo do programa com o mapa completo da **produção vocal**. A instrutora apresenta os **três subsistemas** que trabalham em conjunto: primeiro, o subsistema de **produção de ar** — o ar é a **energia da voz** (\"sem ar, não temos som, não temos voz\"); segundo, o subsistema de **produção de som**, que acontece nas **pregas vocais**, na **laringe** — e aqui ainda temos apenas *som*, não voz; por fim, o trabalho do **trato vocal**, do **trato nasal** e dos **articuladores**, que amplificam e modificam o som, resultando na **voz completa**.\n\nNa sequência, a aula mergulha na fisiologia da **inspiração** por meio de uma pergunta disparadora: o ar entra primeiro, ou a musculatura se contrai primeiro? A resposta mostra que a **musculatura inspiratória** (intercostais externos e diafragma) recebe **estímulos neurológicos**, contrai-se, amplia a **caixa torácica** e só então o ar é puxado para dentro dos pulmões. O movimento das costelas é comparado à **alça de balde** — para fora e para cima — e o **diafragma** desce e expande em toda a sua porção, não apenas na frente do corpo.\n\nPor fim, destaca-se o diafragma como o **músculo mais importante da respiração** e também **músculo postural**: enquanto está ativo, há equilíbrio e sustentação do fluxo de ar; se relaxa, a base da produção vocal \"desmonta\". Como o canto exige muito mais da musculatura do que a fala, a **técnica vocal** existe para refinar esse processo.",
          "notas": "- A aula usa **metodologia interrogativa** (\"pense comigo\") — incentivar o aluno a responder antes de ouvir a explicação.\n- Há **momentos práticos guiados** (inspirar pelo nariz, soltar pela boca, sentir a expansão) — orientar o aluno a executá-los junto ao vídeo.\n- Dois **vídeos demonstrativos** são exibidos dentro da aula (movimento das costelas e do diafragma) — reforçar a observação atenta.\n- Aula **fundamental e cumulativa**: os três subsistemas serão detalhados um a um nas aulas seguintes do módulo.",
