          "prose": "<p>Nesta aula prática, a professora Paula Santana retoma o **subsistema de produção e suporte de ar** e conduz o aluno do entendimento à execução. A revisão inicial reforça que a **contração muscular precede a entrada do ar**: na inspiração, a **musculatura intercostal externa** abre as costelas em **movimento de alça de balde** enquanto o **diafragma** desce. Na emissão da voz, o ar passa pela **região glótica** durante a expiração — mas não deve ser expelido de uma só vez.</p>\n<p>Disso nasce o conceito central da aula: o **apoio vocal**, definido como a *ativação da musculatura inspiratória e sua sustentação durante a emissão do som*. É esse suporte que garante equilíbrio para todos os ajustes posteriores da voz — laríngeos, articulatórios e ressonanciais — e condiciona o canto com **saúde vocal**.</p>\n<p>A prática começa com a **apneia de cinco segundos** e segue com um princípio essencial: respirar para cantar **sem tensão**, vigiando no **espelho** (apresentado como \"grande parceiro de treino do cantor\") os ombros e a região clavicular, que não devem se elevar. Com os polegares sobre as **costelas flutuantes**, o aluno sente a expansão frontal, lateral e posterior; inclinações do tronco ajudam quem tem dificuldade de percepção. Por fim, a aula mostra que o **abdômen participa, mas não lidera**: o apoio exclusivamente abdominal gera tensão que pode **travar a região glótica**. O apoio correto nasce da coordenação entre o foco **diafragmático** e o auxílio da **musculatura abdominal** na sustentação da pressão de ar.</p>",
          "proseRaw": "Nesta aula prática, a professora Paula Santana retoma o **subsistema de produção e suporte de ar** e conduz o aluno do entendimento à execução. A revisão inicial reforça que a **contração muscular precede a entrada do ar**: na inspiração, a **musculatura intercostal externa** abre as costelas em **movimento de alça de balde** enquanto o **diafragma** desce. Na emissão da voz, o ar passa pela **região glótica** durante a expiração — mas não deve ser expelido de uma só vez.\n\nDisso nasce o conceito central da aula: o **apoio vocal**, definido como a *ativação da musculatura inspiratória e sua sustentação durante a emissão do som*. É esse suporte que garante equilíbrio para todos os ajustes posteriores da voz — laríngeos, articulatórios e ressonanciais — e condiciona o canto com **saúde vocal**.\n\nA prática começa com a **apneia de cinco segundos** e segue com um princípio essencial: respirar para cantar **sem tensão**, vigiando no **espelho** (apresentado como \"grande parceiro de treino do cantor\") os ombros e a região clavicular, que não devem se elevar. Com os polegares sobre as **costelas flutuantes**, o aluno sente a expansão frontal, lateral e posterior; inclinações do tronco ajudam quem tem dificuldade de percepção. Por fim, a aula mostra que o **abdômen participa, mas não lidera**: o apoio exclusivamente abdominal gera tensão que pode **travar a região glótica**. O apoio correto nasce da coordenação entre o foco **diafragmático** e o auxílio da **musculatura abdominal** na sustentação da pressão de ar.",
          "notas": "- Aula essencialmente prática: recomenda-se pausar o vídeo e executar cada exercício junto, preferencialmente **em frente ao espelho**, conforme orientação da instrutora.\n- Reforça a natureza **cumulativa** do curso: depende da aula anterior (EP1, subsistemas) e prepara os exercícios de **sustentação do ar**, iniciados ao final da gravação.\n- Ponto de atenção recorrente para correção de vícios: **respiração alta/clavicular** e **apoio abdominal exclusivo** são demonstrados como geradores de tensão glótica.",
