          "prose": "<p>Nesta aula, a professora Paula Santana conclui o mapa dos **três subsistemas da produção vocal**. Depois do **suporte de ar** (a energia) e da **fonte do som na laringe** (o oscilador), chega-se à etapa do **filtro**: o momento em que o som bruto produzido pelas pregas vocais sobe em direção às cavidades do **trato vocal e nasal** para ser **amplificado, moldado e distribuído**. O ponto conceitual central é a distinção entre **som e voz**: na laringe ainda não existe voz — existe som, ruído organizado. É o movimento das estruturas do trato vocal que transforma esse som em voz, permitindo a percepção das **vogais** (pelas formas) e das **consoantes** (pelas articulações).</p>\n<p>A aula também ancora a teoria na prática do louvor. O mesmo trato vocal é \"manuseado\" de modos diferentes conforme o estilo — o cantor lírico, o de MPB, o de rock buscam estéticas distintas. No **canto congregacional**, a estrutura articulatória trabalha em equilíbrio entre graves, médios e agudos com um objetivo claro: **a mensagem do hino**, com texto inteligível, notas e ritmo bem definidos. Por fim, a instrutora reforça que conhecer a fisiologia não é detalhe distante da prática: é o que garante **qualidade e saúde vocal**, cuidada em conjunto por professor de canto, fonoaudiólogo e otorrino.</p>",
          "proseRaw": "Nesta aula, a professora Paula Santana conclui o mapa dos **três subsistemas da produção vocal**. Depois do **suporte de ar** (a energia) e da **fonte do som na laringe** (o oscilador), chega-se à etapa do **filtro**: o momento em que o som bruto produzido pelas pregas vocais sobe em direção às cavidades do **trato vocal e nasal** para ser **amplificado, moldado e distribuído**. O ponto conceitual central é a distinção entre **som e voz**: na laringe ainda não existe voz — existe som, ruído organizado. É o movimento das estruturas do trato vocal que transforma esse som em voz, permitindo a percepção das **vogais** (pelas formas) e das **consoantes** (pelas articulações).\n\nA aula também ancora a teoria na prática do louvor. O mesmo trato vocal é \"manuseado\" de modos diferentes conforme o estilo — o cantor lírico, o de MPB, o de rock buscam estéticas distintas. No **canto congregacional**, a estrutura articulatória trabalha em equilíbrio entre graves, médios e agudos com um objetivo claro: **a mensagem do hino**, com texto inteligível, notas e ritmo bem definidos. Por fim, a instrutora reforça que conhecer a fisiologia não é detalhe distante da prática: é o que garante **qualidade e saúde vocal**, cuidada em conjunto por professor de canto, fonoaudiólogo e otorrino.",
          "notas": "- **Palavra-chave da aula:** *consciência* — cantar sabendo o que o corpo faz.\n- Aula **teórico-fundamentadora**: prepara diretamente o Módulo 5 (articuladores e musculatura) e o Módulo 6 (vogais e consoantes), onde cada estrutura aqui nomeada será treinada.\n- Reforçar com o aluno a memorização do esquema **compressor → oscilador → filtro**, pois ele será reutilizado nas aulas de registros e ressonância.\n- A observação sobre variação bibliográfica (trato vocal com ou sem cavidade nasal) evita confusão quando o aluno consultar outras fontes.",
