          "prose": "<p>Cada voz é única — e o modo como ela fona revela muito sobre seu funcionamento. A aula parte da revisão do **aparelho fonador** e dos **subsistemas da produção vocal** (respiração, fonte e filtro) para mostrar que o que diferencia um modo de fonação de outro acontece na **região glótica**: é o equilíbrio entre a **adução das pregas vocais** (quanto elas se aproximam/fecham) e o **fluxo de ar** que atravessa a glote que gera cada \"textura\" sonora. A intensidade do som, explica a instrutora, é determinada pela quantidade de ar enviada à região glótica.</p>\n<p>Ao longo de um continuum que vai da **abdução** (pregas abertas) à **adução** (pregas fechadas), situam-se os cinco modos: **soproso** (pouca ou nenhuma aproximação, grande perda de ar e risco de ressecamento da laringe), **fluido** (contato completo com leveza, sem tensão — gera **economia vocal** e é típico do canto lírico), **neutro** (aproximação maior, voz mais afirmativa e potente, exigindo fortalecimento muscular), **firme** (volume completo e ar controlado, com atenção redobrada ao volume para não constringir) e **tenso** (apertamento excessivo, canto constantemente no limite, com risco de **lesões** na laringe).</p>\n<p>O ponto de chegada é prático e pessoal: conhecer os modos permite ao cantor **se ouvir** — na fala e no canto, nos graves, médios e agudos —, identificar seu padrão habitual e **diversificar** intencionalmente as texturas vocais. A aula reforça ainda que a voz responde aos **estados emocionais** (tristeza, ansiedade, alegria) por meio do sistema neuromuscular, e que o critério maior em qualquer modo é a **saúde vocal**.</p>",
          "proseRaw": "Cada voz é única — e o modo como ela fona revela muito sobre seu funcionamento. A aula parte da revisão do **aparelho fonador** e dos **subsistemas da produção vocal** (respiração, fonte e filtro) para mostrar que o que diferencia um modo de fonação de outro acontece na **região glótica**: é o equilíbrio entre a **adução das pregas vocais** (quanto elas se aproximam/fecham) e o **fluxo de ar** que atravessa a glote que gera cada \"textura\" sonora. A intensidade do som, explica a instrutora, é determinada pela quantidade de ar enviada à região glótica.\n\nAo longo de um continuum que vai da **abdução** (pregas abertas) à **adução** (pregas fechadas), situam-se os cinco modos: **soproso** (pouca ou nenhuma aproximação, grande perda de ar e risco de ressecamento da laringe), **fluido** (contato completo com leveza, sem tensão — gera **economia vocal** e é típico do canto lírico), **neutro** (aproximação maior, voz mais afirmativa e potente, exigindo fortalecimento muscular), **firme** (volume completo e ar controlado, com atenção redobrada ao volume para não constringir) e **tenso** (apertamento excessivo, canto constantemente no limite, com risco de **lesões** na laringe).\n\nO ponto de chegada é prático e pessoal: conhecer os modos permite ao cantor **se ouvir** — na fala e no canto, nos graves, médios e agudos —, identificar seu padrão habitual e **diversificar** intencionalmente as texturas vocais. A aula reforça ainda que a voz responde aos **estados emocionais** (tristeza, ansiedade, alegria) por meio do sistema neuromuscular, e que o critério maior em qualquer modo é a **saúde vocal**.",
          "notas": "- A instrutora destaca que o conteúdo deve ser absorvido \"a partir do olhar da **individualidade vocal**\" de cada aluno — reforçar isso antes dos exercícios de autoescuta.\n- O modo **firme** é apresentado com ressalva: pouco considerado em artigos acadêmicos; útil registrar para não tratar a classificação como consenso absoluto.\n- Gancho pedagógico com a Aula 23 (`De9y7dRviTU`), que leva os modos de fonação aos **vocalizes** práticos.",
