          "prose": "<p>A aula parte de uma constatação comum no meio vocal: termos como **voz de peito**, **voz de cabeça** e **mix** são amplamente usados, mas geram confusão. A proposta da professora Paula é substituir a descrição por *sensações* pela descrição **fisiológica**: registro vocal é **mecanismo laríngeo**, ou seja, uma configuração de **trabalho muscular da laringe**. Para situar esse fenômeno, ela revisita a imagem dos **três subsistemas** — a musculatura respiratória como **energia** (pressão de ar), a laringe como **fonte** (onde o ar oscila ao passar pelas pregas vocais) e o trato vocal como **filtro** — deixando claro que, embora os três interajam, o foco do estudo é o \"andar\" da fonte.</p>\n<p>Na prática, dois pares musculares protagonizam os mecanismos: nos **graves**, a **tiroaritenóidea** encurta e espessa a prega vocal, aumentando a massa em vibração e a resistência ao ar; nos **agudos**, a **cricotireóidea** tensiona e **estira** a prega. Nenhuma musculatura age isolada — a laringe é um \"corpo vivo dinâmico\". Como num único hino o cantor percorre notas graves, médias e agudas, é preciso **administrar a transição** entre configurações: quando essa passagem não é equilibrada, ocorre a **quebra vocal**, demonstrada na aula. A partir daí, a professora propõe exercícios — escala de Dó com vogal **U**, **glissando** \"preguiçoso\" e o **exercício do espaguete** — nomeando **M1** (peito) e **M2** (cabeça) e alertando para o erro frequente de **tensionar os lábios** nos agudos: a solução é **abrir espaço interno** no trato vocal, mantendo a musculatura vizinha relaxada enquanto a laringe realiza o alongamento.</p>",
          "proseRaw": "A aula parte de uma constatação comum no meio vocal: termos como **voz de peito**, **voz de cabeça** e **mix** são amplamente usados, mas geram confusão. A proposta da professora Paula é substituir a descrição por *sensações* pela descrição **fisiológica**: registro vocal é **mecanismo laríngeo**, ou seja, uma configuração de **trabalho muscular da laringe**. Para situar esse fenômeno, ela revisita a imagem dos **três subsistemas** — a musculatura respiratória como **energia** (pressão de ar), a laringe como **fonte** (onde o ar oscila ao passar pelas pregas vocais) e o trato vocal como **filtro** — deixando claro que, embora os três interajam, o foco do estudo é o \"andar\" da fonte.\n\nNa prática, dois pares musculares protagonizam os mecanismos: nos **graves**, a **tiroaritenóidea** encurta e espessa a prega vocal, aumentando a massa em vibração e a resistência ao ar; nos **agudos**, a **cricotireóidea** tensiona e **estira** a prega. Nenhuma musculatura age isolada — a laringe é um \"corpo vivo dinâmico\". Como num único hino o cantor percorre notas graves, médias e agudas, é preciso **administrar a transição** entre configurações: quando essa passagem não é equilibrada, ocorre a **quebra vocal**, demonstrada na aula. A partir daí, a professora propõe exercícios — escala de Dó com vogal **U**, **glissando** \"preguiçoso\" e o **exercício do espaguete** — nomeando **M1** (peito) e **M2** (cabeça) e alertando para o erro frequente de **tensionar os lábios** nos agudos: a solução é **abrir espaço interno** no trato vocal, mantendo a musculatura vizinha relaxada enquanto a laringe realiza o alongamento.",
          "notas": "- A aula pressupõe o **Módulo 3** (três subsistemas) e dialoga com a Aula 20/EP20 (modos de fonação): reforce a distinção **mecanismo (M1/M2) ≠ modo de fonação**.\n- Incentive o aluno a **pausar o vídeo** e repetir os exercícios em tons adequados à própria classificação vocal, como a própria instrutora sugere (vozes graves podem permanecer na região grave).\n- A demonstração da **quebra vocal** (t≈727s) é um recurso valioso: peça ao aluno que identifique a *sua* zona de instabilidade antes de tentar suavizá-la.",
