          "prose": "<p>A aula abre estabelecendo a distinção central do Módulo 4: enquanto os **mecanismos laríngeos** dizem respeito a **frequências e notas** — como a musculatura da laringe se comporta ao longo da **extensão vocal** (grave, médio, agudo) —, os **modos de fonação** tratam do **nível de aproximação (adução) das pregas vocais** e de **quanto ar passa pela glote**, **independentemente da nota** cantada. É possível, portanto, cantar a mesma melodia inteira em modo soproso, neutro ou firme.</p>\n<p>O percurso segue uma escala progressiva de fechamento glótico: **sussurrado** (abdução completa, quase sem vibração — muito mais ar do que som), **soproso** (há som, mas com muito ar; pode indicar **fenda** ou ser intencional), **fluido** (voz leve e agradável, sem ar audível — a referência é a \"voz do GPS\"), **neutro** (mais firmeza e aproximação), **firme** (bastante adução, peso e intensidade em qualquer região) e **tenso** (adução completa, grande resistência do ar — **zona de risco**, com constrição, participação da epiglote e possibilidade de **lesões**). A instrutora alerta ainda que os modos mais abertos podem gerar **ressecamento** da estrutura laríngea, e que do neutro ao firme aumentam as **forças de colisão**, exigindo consciência e **tônus muscular**.</p>\n<p>O fechamento da aula é aplicativo: o aluno é convidado a **identificar seu modo de fonação habitual** — soproso, neutro, firme ou tenso — e a analisar seu padrão vocal, entendendo que mesmo efeitos \"tensos\" de estilos como sertanejo e rock só são aceitáveis quando executados com **consciência vocal**, nunca com tensão.</p>",
          "proseRaw": "A aula abre estabelecendo a distinção central do Módulo 4: enquanto os **mecanismos laríngeos** dizem respeito a **frequências e notas** — como a musculatura da laringe se comporta ao longo da **extensão vocal** (grave, médio, agudo) —, os **modos de fonação** tratam do **nível de aproximação (adução) das pregas vocais** e de **quanto ar passa pela glote**, **independentemente da nota** cantada. É possível, portanto, cantar a mesma melodia inteira em modo soproso, neutro ou firme.\n\nO percurso segue uma escala progressiva de fechamento glótico: **sussurrado** (abdução completa, quase sem vibração — muito mais ar do que som), **soproso** (há som, mas com muito ar; pode indicar **fenda** ou ser intencional), **fluido** (voz leve e agradável, sem ar audível — a referência é a \"voz do GPS\"), **neutro** (mais firmeza e aproximação), **firme** (bastante adução, peso e intensidade em qualquer região) e **tenso** (adução completa, grande resistência do ar — **zona de risco**, com constrição, participação da epiglote e possibilidade de **lesões**). A instrutora alerta ainda que os modos mais abertos podem gerar **ressecamento** da estrutura laríngea, e que do neutro ao firme aumentam as **forças de colisão**, exigindo consciência e **tônus muscular**.\n\nO fechamento da aula é aplicativo: o aluno é convidado a **identificar seu modo de fonação habitual** — soproso, neutro, firme ou tenso — e a analisar seu padrão vocal, entendendo que mesmo efeitos \"tensos\" de estilos como sertanejo e rock só são aceitáveis quando executados com **consciência vocal**, nunca com tensão.",
