          "prose": "<p>A aula abre estabelecendo uma distinção fundamental para todo o estudo de registros: **extensão vocal** é o intervalo entre a nota mais grave e a mais aguda que o corpo emite **naturalmente**, sem nenhum treinamento — é fruto da condição fisiológica de cada um. Já a **tessitura vocal** é a região de maior **destaque, amplitude e beleza**, e essa sim se desenvolve com trabalho técnico, ajustes articulatórios e ressonâncias. Conhecer a própria extensão é o caminho para identificar a tessitura.</p>\n<p>A instrutora reforça que cada região da extensão é produzida por um **mecanismo laríngeo** distinto: no grave, a prega vocal está mais **encurtada e com mais massa muscular** (som denso e potente); no agudo, mais **alongada e leve**. Por isso, \"registro de peito\" e \"registro de cabeça\" são nomes de **mecanismos fisiológicos**, não indicações de que a voz esteja no tórax ou na cabeça. Extensão e textura são profundamente **individuais** — biotipo, anatomia e até fatores emocionais as constroem.</p>\n<p>Na prática, o vocalize usa a **vogal U** para manter o **trato vocal alongado** e a laringe baixa, percorrendo uma escala a partir de Lá maior. As orientações centrais: descer ao grave com **leveza** (\"som grave suspenso\"), subir sem força, perceber o ponto em que a fisiologia sinaliza a **troca de registro**, e promover **abertura orofaríngea** nos agudos. O objetivo final é uma extensão **uniforme**, sem \"duas vozes\" diferentes entre grave e agudo — e sempre sem tensão na musculatura.</p>",
          "proseRaw": "A aula abre estabelecendo uma distinção fundamental para todo o estudo de registros: **extensão vocal** é o intervalo entre a nota mais grave e a mais aguda que o corpo emite **naturalmente**, sem nenhum treinamento — é fruto da condição fisiológica de cada um. Já a **tessitura vocal** é a região de maior **destaque, amplitude e beleza**, e essa sim se desenvolve com trabalho técnico, ajustes articulatórios e ressonâncias. Conhecer a própria extensão é o caminho para identificar a tessitura.\n\nA instrutora reforça que cada região da extensão é produzida por um **mecanismo laríngeo** distinto: no grave, a prega vocal está mais **encurtada e com mais massa muscular** (som denso e potente); no agudo, mais **alongada e leve**. Por isso, \"registro de peito\" e \"registro de cabeça\" são nomes de **mecanismos fisiológicos**, não indicações de que a voz esteja no tórax ou na cabeça. Extensão e textura são profundamente **individuais** — biotipo, anatomia e até fatores emocionais as constroem.\n\nNa prática, o vocalize usa a **vogal U** para manter o **trato vocal alongado** e a laringe baixa, percorrendo uma escala a partir de Lá maior. As orientações centrais: descer ao grave com **leveza** (\"som grave suspenso\"), subir sem força, perceber o ponto em que a fisiologia sinaliza a **troca de registro**, e promover **abertura orofaríngea** nos agudos. O objetivo final é uma extensão **uniforme**, sem \"duas vozes\" diferentes entre grave e agudo — e sempre sem tensão na musculatura.",
