          "prose": "<p>A aula é inteiramente prática e integra o **condicionamento vocal** contínuo do cantor. A instrutora parte dos **articuladores** — com destaque para a **língua**, principal responsável pelo molde do som — e conduz uma sequência de exercícios simples de mobilidade e flexibilidade, sempre com a mesma régua: a musculatura não pode estar **nem frouxa nem tensa**, pois toda a produção vocal depende de **equilíbrio estrutural**.</p>\n<p>Um ponto fisiológico central é a **conexão língua–laringe**: a tensão lingual migra para a estrutura laríngea e compromete a emissão. Por isso, os exercícios incluem a percepção do movimento da laringe (subida/descida, como num \"**bocejo reprimido**\"), a **massagem laríngea** com dois dedos e a **sucção do ar**, que abaixa a laringe e expande o trato vocal. A aplicação melódica (vibração de língua na forma da vogal **U**, sopro + U, U–I com mudanças sutis) consolida o trabalho, com o alerta postural de que inclinar a cabeça para alcançar agudos produz **constrição** — e a recomendação recorrente de treinar **em frente ao espelho**, pois cada corpo responde de forma individual.</p>\n<p>> **Nota didática:** incentive o aluno a registrar as próprias respostas (tremor, tensão, alcance dos movimentos) a cada sessão — a instrutora enfatiza que a resposta muscular é individual e deve guiar a progressão do treino.</p>",
          "proseRaw": "A aula é inteiramente prática e integra o **condicionamento vocal** contínuo do cantor. A instrutora parte dos **articuladores** — com destaque para a **língua**, principal responsável pelo molde do som — e conduz uma sequência de exercícios simples de mobilidade e flexibilidade, sempre com a mesma régua: a musculatura não pode estar **nem frouxa nem tensa**, pois toda a produção vocal depende de **equilíbrio estrutural**.\n\nUm ponto fisiológico central é a **conexão língua–laringe**: a tensão lingual migra para a estrutura laríngea e compromete a emissão. Por isso, os exercícios incluem a percepção do movimento da laringe (subida/descida, como num \"**bocejo reprimido**\"), a **massagem laríngea** com dois dedos e a **sucção do ar**, que abaixa a laringe e expande o trato vocal. A aplicação melódica (vibração de língua na forma da vogal **U**, sopro + U, U–I com mudanças sutis) consolida o trabalho, com o alerta postural de que inclinar a cabeça para alcançar agudos produz **constrição** — e a recomendação recorrente de treinar **em frente ao espelho**, pois cada corpo responde de forma individual.\n\n> **Nota didática:** incentive o aluno a registrar as próprias respostas (tremor, tensão, alcance dos movimentos) a cada sessão — a instrutora enfatiza que a resposta muscular é individual e deve guiar a progressão do treino.",
