          "prose": "<p>Nesta aula prática, a professora Paula Santana conduz o aluno pelos primeiros exercícios de **consciência articulatória**, começando por um princípio essencial: embora os **articuladores trabalhem sempre em conjunto**, cada exercício destina a atenção a um deles de cada vez. A aula introduz ainda um tema que será aprofundado adiante: a **musculatura facial** participa ativamente da sonoridade — o movimento do rosto **não é só estético, é fisiológico e sonoro**.</p>\n<p>O primeiro articulador trabalhado é a **mandíbula**, cuja mobilidade é condição para a inteligibilidade da fala e do canto. O aluno é orientado a perceber a **ATM** (à frente das orelhas), evitando as extremidades de movimento que geram desconforto, e a manter a **cavidade oral expandida** — como num bocejo — especialmente nas regiões grave e aguda, sem colocar peso no som. Durante os exercícios (\"uá\" e \"moi\"), a **língua** deve permanecer com o **ápice na raiz dos dentes**, relaxada: língua recuada ou tensa gera prejuízos ao canto.</p>\n<p>Em seguida, o foco vai para os **lábios**, sempre em relação com a musculatura vizinha (**risório, bucinador, levantador do lábio superior, zigomáticos**). Na **vibração de lábios**, os dentes ficam afastados (cerca de \"uma unha\" de espaço): dentes apertados criam um **padrão de tensão** que se transfere às **pregas vocais**. Quanto mais aguda a região, mais **leveza e espaço** o som pede.</p>\n<p>> **Nota didática:** a instrutora (soprano) esclarece que o objetivo não é extensão vocal, e sim o trabalho articulatório — cada aluno deve respeitar a própria tessitura. Aula para ser feita **junto com o vídeo**, ao piano.</p>",
          "proseRaw": "Nesta aula prática, a professora Paula Santana conduz o aluno pelos primeiros exercícios de **consciência articulatória**, começando por um princípio essencial: embora os **articuladores trabalhem sempre em conjunto**, cada exercício destina a atenção a um deles de cada vez. A aula introduz ainda um tema que será aprofundado adiante: a **musculatura facial** participa ativamente da sonoridade — o movimento do rosto **não é só estético, é fisiológico e sonoro**.\n\nO primeiro articulador trabalhado é a **mandíbula**, cuja mobilidade é condição para a inteligibilidade da fala e do canto. O aluno é orientado a perceber a **ATM** (à frente das orelhas), evitando as extremidades de movimento que geram desconforto, e a manter a **cavidade oral expandida** — como num bocejo — especialmente nas regiões grave e aguda, sem colocar peso no som. Durante os exercícios (\"uá\" e \"moi\"), a **língua** deve permanecer com o **ápice na raiz dos dentes**, relaxada: língua recuada ou tensa gera prejuízos ao canto.\n\nEm seguida, o foco vai para os **lábios**, sempre em relação com a musculatura vizinha (**risório, bucinador, levantador do lábio superior, zigomáticos**). Na **vibração de lábios**, os dentes ficam afastados (cerca de \"uma unha\" de espaço): dentes apertados criam um **padrão de tensão** que se transfere às **pregas vocais**. Quanto mais aguda a região, mais **leveza e espaço** o som pede.\n\n> **Nota didática:** a instrutora (soprano) esclarece que o objetivo não é extensão vocal, e sim o trabalho articulatório — cada aluno deve respeitar a própria tessitura. Aula para ser feita **junto com o vídeo**, ao piano.",
