          "prose": "<p>A instrutora abre a aula desfazendo um equívoco comum: a musculatura do rosto **não serve apenas à expressão estética** da interpretação. Toda a movimentação da face participa fisiologicamente da produção vocal, influenciando os **articuladores**, as estruturas do **trato vocal** e, por reflexo, até a região laríngea. Quanto maior a consciência e o treino dessa musculatura, maior a qualidade da voz — na fala e, com ainda mais exigência, no canto.</p>\n<p>O conceito central da aula é a **embocadura**. Assim como o flautista estuda o posicionamento exato dos lábios no bocal para obter um som de qualidade, o cantor precisa estudar o modo de **projetar o fluxo de ar e o som** com a musculatura da face. Outro ponto fundamental é a **fáscia**, a película que reveste toda a musculatura: por causa dessa interligação, o movimento de um músculo gera **reflexos de contração ou relaxamento** em outros — mais uma prova de que, no corpo, nada funciona isoladamente.</p>\n<p>Na prática, a aula conduz uma ginástica facial progressiva: **bico e sorriso** (ativando zigomáticos maior e menor, orbicular dos lábios, risório e bucinador), elevação das bochechas, sobrancelhas e o levantamento do **lábio superior**. A instrutora normaliza o aspecto \"feio\" desses movimentos — cantar é uma atividade **física**, e o objetivo é extrair o melhor som possível. Ela também diagnostica o **lábio trêmulo** em notas agudas como sinal de tensão, que o treino regular ajuda a eliminar: a ativação dessa musculatura depende de **memória, repetição e condicionamento**, devendo entrar no treino diário.</p>\n<p>Dois fechamentos integram a aula ao restante do curso. Primeiro, a ponte com a aula anterior: ao levantar o lábio superior, o aluno é convidado a **sentir o palato mole se elevar** — a face participa da movimentação desse articulador interno. Segundo, a intencionalidade: no exercício \"brim\", fazer com ou sem o posicionamento facial (lábio superior elevado, zigomáticos ativos) produz resultados sonoros diferentes — cabe ao cantor **discernir o objetivo do exercício** (som mais metálico, brilhante, projetado \"para frente\") e montar a embocadura correspondente. A aula termina aplicando esse trabalho muscular à primeira frase do hino *\"Os céus declaram a glória de Deus\"*, mostrando que o repertório de louvor já exige, desde o primeiro verso, uma face treinada.</p>",
          "proseRaw": "A instrutora abre a aula desfazendo um equívoco comum: a musculatura do rosto **não serve apenas à expressão estética** da interpretação. Toda a movimentação da face participa fisiologicamente da produção vocal, influenciando os **articuladores**, as estruturas do **trato vocal** e, por reflexo, até a região laríngea. Quanto maior a consciência e o treino dessa musculatura, maior a qualidade da voz — na fala e, com ainda mais exigência, no canto.\n\nO conceito central da aula é a **embocadura**. Assim como o flautista estuda o posicionamento exato dos lábios no bocal para obter um som de qualidade, o cantor precisa estudar o modo de **projetar o fluxo de ar e o som** com a musculatura da face. Outro ponto fundamental é a **fáscia**, a película que reveste toda a musculatura: por causa dessa interligação, o movimento de um músculo gera **reflexos de contração ou relaxamento** em outros — mais uma prova de que, no corpo, nada funciona isoladamente.\n\nNa prática, a aula conduz uma ginástica facial progressiva: **bico e sorriso** (ativando zigomáticos maior e menor, orbicular dos lábios, risório e bucinador), elevação das bochechas, sobrancelhas e o levantamento do **lábio superior**. A instrutora normaliza o aspecto \"feio\" desses movimentos — cantar é uma atividade **física**, e o objetivo é extrair o melhor som possível. Ela também diagnostica o **lábio trêmulo** em notas agudas como sinal de tensão, que o treino regular ajuda a eliminar: a ativação dessa musculatura depende de **memória, repetição e condicionamento**, devendo entrar no treino diário.\n\nDois fechamentos integram a aula ao restante do curso. Primeiro, a ponte com a aula anterior: ao levantar o lábio superior, o aluno é convidado a **sentir o palato mole se elevar** — a face participa da movimentação desse articulador interno. Segundo, a intencionalidade: no exercício \"brim\", fazer com ou sem o posicionamento facial (lábio superior elevado, zigomáticos ativos) produz resultados sonoros diferentes — cabe ao cantor **discernir o objetivo do exercício** (som mais metálico, brilhante, projetado \"para frente\") e montar a embocadura correspondente. A aula termina aplicando esse trabalho muscular à primeira frase do hino *\"Os céus declaram a glória de Deus\"*, mostrando que o repertório de louvor já exige, desde o primeiro verso, uma face treinada.",
          "notas": "- **Pré-requisito explícito:** a instrutora referencia diretamente a aula de **palato mole** (`IYCnhMufVfw`); recomenda-se revisá-la antes dos exercícios de integração lábio–palato.\n- **Ponto de atenção postural:** no exercício dos músculos do canto da boca, o movimento deve ser **puramente muscular, sem movimentar a mandíbula** — observe os alunos quanto a compensações.\n- **Sugestão de prática:** propor o teste guiado \"abaixou/levantou\" (mão leve no rosto, atenção ao céu da boca) para o aluno perceber o reflexo do levantamento labial no palato mole.",
