          "prose": "<p>A aula parte de um princípio já estudado: assim como a musculatura se organiza **antes** do início do som, cada **vogal** também se posiciona no **trato vocal** antes de a voz ser emitida. Cantar com consciência, portanto, exige conhecer a **postura muscular** de cada vogal, pois é ela que define o **filtro** — o molde que o som gerado na **laringe** recebe ao atravessar o trato.</p>\n<p>A classificação proposta observa dois parâmetros da **língua**: o **ponto de altura** (se a elevação ocorre no ápice, no meio ou no dorso) e o **ponto de constrição** (o estreitamento entre a língua e a parede faríngea). Disso decorre a distinção entre **vogais frontais** e **posteriores**, e entre sons mais **abertos** ou **fechados**. Nas abertas (I, É, E, A), o I é a mais alta, com o dorso próximo ao **palato duro**; nas fechadas (U, O, Ô, A), o U é a mais alta e posterior, e o Ô oferece mais espaço na região **orofaríngea** que o O fechado.</p>\n<p>O treino enfatiza a **sutileza**: mandíbula, lábios e língua devem se mover naturalmente, sem projeção da **ATM** nem gestos exagerados, que cansam os **articuladores**. O **palato mole** recebe atenção especial: sua expansão (facilitada pela inspiração nasal) evita o som apertado e **nasalado**, buscando um espaço **equilibrado** — nem constrição, nem a cobertura ampla do canto lírico — adequado à sonoridade congregacional do louvor. Ao final, respiração, ataque e vogais são integrados num vocalizo de cinco notas, com a primeira nota mais firme e a segunda mais leve, respeitando a diferença de altura e preparando a **extensão vocal**.</p>",
          "proseRaw": "A aula parte de um princípio já estudado: assim como a musculatura se organiza **antes** do início do som, cada **vogal** também se posiciona no **trato vocal** antes de a voz ser emitida. Cantar com consciência, portanto, exige conhecer a **postura muscular** de cada vogal, pois é ela que define o **filtro** — o molde que o som gerado na **laringe** recebe ao atravessar o trato.\n\nA classificação proposta observa dois parâmetros da **língua**: o **ponto de altura** (se a elevação ocorre no ápice, no meio ou no dorso) e o **ponto de constrição** (o estreitamento entre a língua e a parede faríngea). Disso decorre a distinção entre **vogais frontais** e **posteriores**, e entre sons mais **abertos** ou **fechados**. Nas abertas (I, É, E, A), o I é a mais alta, com o dorso próximo ao **palato duro**; nas fechadas (U, O, Ô, A), o U é a mais alta e posterior, e o Ô oferece mais espaço na região **orofaríngea** que o O fechado.\n\nO treino enfatiza a **sutileza**: mandíbula, lábios e língua devem se mover naturalmente, sem projeção da **ATM** nem gestos exagerados, que cansam os **articuladores**. O **palato mole** recebe atenção especial: sua expansão (facilitada pela inspiração nasal) evita o som apertado e **nasalado**, buscando um espaço **equilibrado** — nem constrição, nem a cobertura ampla do canto lírico — adequado à sonoridade congregacional do louvor. Ao final, respiração, ataque e vogais são integrados num vocalizo de cinco notas, com a primeira nota mais firme e a segunda mais leve, respeitando a diferença de altura e preparando a **extensão vocal**.",
