          "prose": "<p>Nesta aula, a professora Paula Santana explica **como as vogais nascem** da movimentação dos articuladores no trato vocal. O percurso anatômico vai de trás para frente: a **laringe** (cujos movimentos influenciam a sonoridade), a **faringe** em suas três porções, o **palato mole** funcionando como **válvula** entre as ressonâncias oral e nasal, e, na parte anterior, **mandíbula**, **lábios** e **língua** — esta última apresentada como o grande elemento diferenciador de uma vogal em relação às demais.</p>\n<p>O eixo prático da aula são os **três parâmetros de análise** de qualquer vogal: o **formato dos lábios** (arredondados, como no U; estirados, como no I), o **posicionamento da língua** (anterior, central ou posterior — lembrando que a porção posterior se conecta diretamente à laringe e influencia sua postura) e o **nível de abertura** (fechada, meio fechada, meio aberta, aberta). Dominar esses parâmetros dá ao cantor **consciência fisiológica** para direcionar estratégias de ressonância.</p>\n<p>Dois alertas fecham a aula. Primeiro: **articular bem não é questão estética** — a expressão é consequência; o objetivo é produzir o som adequado **poupando a musculatura laríngea**, já que o bom trabalho do **filtro** (trato vocal) sustenta o que é gerado na **fonte** (laringe). Segundo: o canto é **individual** — cada trato vocal tem seu ajuste ideal —, embora o trabalho em **coro** exija exercícios pensados para a sonoridade do conjunto. Por fim, a **abertura mandibular** amplia a cavidade oral e facilita os **agudos** com menos constrição, o que torna essencial cuidar da **ATM** e das tensões da musculatura do pescoço.</p>",
          "proseRaw": "Nesta aula, a professora Paula Santana explica **como as vogais nascem** da movimentação dos articuladores no trato vocal. O percurso anatômico vai de trás para frente: a **laringe** (cujos movimentos influenciam a sonoridade), a **faringe** em suas três porções, o **palato mole** funcionando como **válvula** entre as ressonâncias oral e nasal, e, na parte anterior, **mandíbula**, **lábios** e **língua** — esta última apresentada como o grande elemento diferenciador de uma vogal em relação às demais.\n\nO eixo prático da aula são os **três parâmetros de análise** de qualquer vogal: o **formato dos lábios** (arredondados, como no U; estirados, como no I), o **posicionamento da língua** (anterior, central ou posterior — lembrando que a porção posterior se conecta diretamente à laringe e influencia sua postura) e o **nível de abertura** (fechada, meio fechada, meio aberta, aberta). Dominar esses parâmetros dá ao cantor **consciência fisiológica** para direcionar estratégias de ressonância.\n\nDois alertas fecham a aula. Primeiro: **articular bem não é questão estética** — a expressão é consequência; o objetivo é produzir o som adequado **poupando a musculatura laríngea**, já que o bom trabalho do **filtro** (trato vocal) sustenta o que é gerado na **fonte** (laringe). Segundo: o canto é **individual** — cada trato vocal tem seu ajuste ideal —, embora o trabalho em **coro** exija exercícios pensados para a sonoridade do conjunto. Por fim, a **abertura mandibular** amplia a cavidade oral e facilita os **agudos** com menos constrição, o que torna essencial cuidar da **ATM** e das tensões da musculatura do pescoço.",
