          "prose": "<p>Nesta aula, o estudo das vogais deixa de ser descritivo e se torna **ferramenta de decisão**: cada vogal é apresentada como resposta a um problema concreto de emissão. O ponto de partida é a **língua**, articulador de maior influência no canto pelo seu volume muscular, e a relação direta entre sua postura e a **altura da laringe** — língua anterior e alta eleva a laringe; língua posterior a rebaixa.</p>\n<p>A partir daí, a instrutora propõe um raciocínio de **diagnóstico vocal**: se o cantor tem som **escuro, posterior, \"entubado\"**, usa-se a **vogal I** (lábios estirados, língua alta anteriorizada) para trazer **frontalidade e brilho** — com o cuidado de manter espaço entre os dentes e ampliar a **abertura mandibular** na região aguda, sob risco de som apertado e estridente. Se a necessidade é **leveza**, menos impacto e acesso facilitado ao **registro de cabeça**, usa-se a **vogal U**, que abaixa a laringe e **alonga o trato vocal**. As combinações **U–I** e **I–U** permitem **deslocar o som** de trás para frente (ou o inverso) dentro de um mesmo exercício, inclusive para quebrar padrões fixos de lábios estirados ou arredondados em demasia. Fecham a aula a **vogal E** para equilibrar **nasalidade** (via posicionamento do **palato mole**) e as **vogais posteriores O/U** para sonoridade mais **verticalizada**, de perfil clássico.</p>\n<p>**Nota didática:** atenção à autocorreção da instrutora (~t=830): para trazer o som de trás para frente, a sequência correta é **U → I**, e não I → U. Vale reforçar esse detalhe no material escrito, pois exemplifica bem a lógica \"vogal posterior → vogal anterior\".</p>",
          "proseRaw": "Nesta aula, o estudo das vogais deixa de ser descritivo e se torna **ferramenta de decisão**: cada vogal é apresentada como resposta a um problema concreto de emissão. O ponto de partida é a **língua**, articulador de maior influência no canto pelo seu volume muscular, e a relação direta entre sua postura e a **altura da laringe** — língua anterior e alta eleva a laringe; língua posterior a rebaixa.\n\nA partir daí, a instrutora propõe um raciocínio de **diagnóstico vocal**: se o cantor tem som **escuro, posterior, \"entubado\"**, usa-se a **vogal I** (lábios estirados, língua alta anteriorizada) para trazer **frontalidade e brilho** — com o cuidado de manter espaço entre os dentes e ampliar a **abertura mandibular** na região aguda, sob risco de som apertado e estridente. Se a necessidade é **leveza**, menos impacto e acesso facilitado ao **registro de cabeça**, usa-se a **vogal U**, que abaixa a laringe e **alonga o trato vocal**. As combinações **U–I** e **I–U** permitem **deslocar o som** de trás para frente (ou o inverso) dentro de um mesmo exercício, inclusive para quebrar padrões fixos de lábios estirados ou arredondados em demasia. Fecham a aula a **vogal E** para equilibrar **nasalidade** (via posicionamento do **palato mole**) e as **vogais posteriores O/U** para sonoridade mais **verticalizada**, de perfil clássico.\n\n**Nota didática:** atenção à autocorreção da instrutora (~t=830): para trazer o som de trás para frente, a sequência correta é **U → I**, e não I → U. Vale reforçar esse detalhe no material escrito, pois exemplifica bem a lógica \"vogal posterior → vogal anterior\".",
