          "prose": "<p>A aula parte da recapitulação das **vogais** — formadas com o **trato vocal livre**, sem interrupção do fluxo de ar — para introduzir o contraste fundamental: nas **consoantes**, algum **articulador obstrui a passagem do ar** e, consequentemente, **do som**, de forma **parcial ou total**. É essa obstrução que define a fronteira entre vogal e consoante.</p>\n<p>Para classificar as consoantes, a instrutora apresenta três critérios: o **modo de articulação** (como o fluxo de ar passa), o **ponto de articulação** (quais articuladores entram em contato) e o **vozeamento** (se há ou não **vibração das pregas vocais**). Consoantes **vozeadas** produzem som; as **não vozeadas**, sem vibração da fonte sonora, são justamente as usadas nos **exercícios respiratórios de controle de fluxo de ar** — conexão direta com o Módulo 2.</p>\n<p>Nos modos de articulação, a aula demonstra as **oclusivas/explosivas** (P, Q, T — obstrução **total, forte e rápida**), as **fricativas** (Z, V — obstrução **parcial** que gera **ruído/fricção**) e as **nasais** (fluxo liberado pela **cavidade nasal**). O fechamento prático convida o aluno a **analisar o comportamento do trato vocal** na sílaba exata em que o canto falha — verificando abertura de boca, posição e tensão da língua, lábios e o grau de obstrução da consoante — transformando teoria em **ajuste consciente e inteligente** durante o louvor.</p>",
          "proseRaw": "A aula parte da recapitulação das **vogais** — formadas com o **trato vocal livre**, sem interrupção do fluxo de ar — para introduzir o contraste fundamental: nas **consoantes**, algum **articulador obstrui a passagem do ar** e, consequentemente, **do som**, de forma **parcial ou total**. É essa obstrução que define a fronteira entre vogal e consoante.\n\nPara classificar as consoantes, a instrutora apresenta três critérios: o **modo de articulação** (como o fluxo de ar passa), o **ponto de articulação** (quais articuladores entram em contato) e o **vozeamento** (se há ou não **vibração das pregas vocais**). Consoantes **vozeadas** produzem som; as **não vozeadas**, sem vibração da fonte sonora, são justamente as usadas nos **exercícios respiratórios de controle de fluxo de ar** — conexão direta com o Módulo 2.\n\nNos modos de articulação, a aula demonstra as **oclusivas/explosivas** (P, Q, T — obstrução **total, forte e rápida**), as **fricativas** (Z, V — obstrução **parcial** que gera **ruído/fricção**) e as **nasais** (fluxo liberado pela **cavidade nasal**). O fechamento prático convida o aluno a **analisar o comportamento do trato vocal** na sílaba exata em que o canto falha — verificando abertura de boca, posição e tensão da língua, lábios e o grau de obstrução da consoante — transformando teoria em **ajuste consciente e inteligente** durante o louvor.",
          "notas": "- **Pré-requisitos explícitos:** a própria instrutora remete às aulas anteriores de vogais (`8TTSqgLWENY`, `ZI9gb9mzOGY`, `lIbdWIC6c7g`); garantir esse percurso antes desta aula.\n- **Ponte com respiração:** a menção às consoantes não vozeadas retoma os exercícios de fluxo de ar do Módulo 2 — oportunidade de revisão integrada.\n- **Transcrição truncada:** o material fornecido encerra durante o modo **nasal**; o enriquecimento cobre apenas o trecho disponível. Se houver continuação (outros modos, exemplos cantados), complementar depois.\n- Sugerir ao aluno o exercício de **autodiagnóstico** proposto em t=357: escolher um trecho difícil de um hino e mapear vogal + consoante da sílaba problemática.",
          "exercicios": "Prática vocal e exercícios específicos ministrados pela Prof.ª Paula Santana para o Módulo 6."
