          "prose": "<p>Nesta aula, a instrutora apresenta o **condicionamento vocal** como a base para uma boa **emissão**: é ele que **habilita**, **prepara** e **torna apta** a voz para determinado repertório e padrão de qualidade. Como cada **instrumento é individual**, o condicionamento também será particular — e exige **tempo de treino** separado com intencionalidade. O cantor é comparado a um **atleta da voz**, pois cantar é atividade física que envolve músculos, ligamentos e tendões.</p>\n<p>O condicionamento se apoia em três pontos-chave: a **estrutura cardiorrespiratória** (eficiência vocal e recuperação mais rápida após o uso), a **flexibilidade** (ilustrada pela imagem da bailarina: cantar é uma \"coreografia sonora\" que pede movimentos leves e elásticos — a rigidez faz o sistema gastar mais energia) e o **equilíbrio de forças** (que reduz lesões; fadiga, falta de resposta e compensações desequilibradas são sinais de alerta). O equilíbrio entre os três gera **qualidade e economia vocal** — cantar com o **menor esforço possível**, retomando o conceito de \"cantar no lucro\" visto na aula de modos de fonação. Sobre essa base, são introduzidos os **princípios do treinamento vocal** — **sobrecarga**, **individualidade**, **especificidade** e **reversibilidade** — que funcionam em constante interação.</p>",
          "proseRaw": "Nesta aula, a instrutora apresenta o **condicionamento vocal** como a base para uma boa **emissão**: é ele que **habilita**, **prepara** e **torna apta** a voz para determinado repertório e padrão de qualidade. Como cada **instrumento é individual**, o condicionamento também será particular — e exige **tempo de treino** separado com intencionalidade. O cantor é comparado a um **atleta da voz**, pois cantar é atividade física que envolve músculos, ligamentos e tendões.\n\nO condicionamento se apoia em três pontos-chave: a **estrutura cardiorrespiratória** (eficiência vocal e recuperação mais rápida após o uso), a **flexibilidade** (ilustrada pela imagem da bailarina: cantar é uma \"coreografia sonora\" que pede movimentos leves e elásticos — a rigidez faz o sistema gastar mais energia) e o **equilíbrio de forças** (que reduz lesões; fadiga, falta de resposta e compensações desequilibradas são sinais de alerta). O equilíbrio entre os três gera **qualidade e economia vocal** — cantar com o **menor esforço possível**, retomando o conceito de \"cantar no lucro\" visto na aula de modos de fonação. Sobre essa base, são introduzidos os **princípios do treinamento vocal** — **sobrecarga**, **individualidade**, **especificidade** e **reversibilidade** — que funcionam em constante interação.",
          "notas": "- Conecta-se diretamente à **Aula 20 (modos de fonação)**, citada pela instrutora ao explicar economia vocal — bom momento para revisitar aquele conteúdo.\n- A **individualidade** é fio condutor da aula: o professor orienta o caminho, mas o cantor é quem administra a própria produção vocal e precisa conhecer seus limites.\n- ⚠️ A transcrição fornecida está **truncada** durante a explicação do princípio da sobrecarga; evite afirmar conteúdo além do trecho disponível.",
