          "prose": "<p>Nesta aula, a professora Paula Santana apresenta o **aquecimento vocal** como etapa indispensável — e propõe que o aluno pense em **aquecimento corporal e vocal**, pois o instrumento do cantor é o próprio corpo. Assim como um atleta prepara o corpo antes do esforço, o cantor é um **atleta da voz**: cantar exige que musculaturas, tecidos e ligamentos trabalhem de forma mais intensa e coordenada.</p>\n<p>O **objetivo geral** do aquecimento é preparar as estruturas fisiológicas para a voz cantada. Dele derivam objetivos específicos: aumentar **energia muscular e respiratória**, **circulação sanguínea** e **oxigenação**, equilibrar o **fluxo de ar** e, sobretudo, manter a **saúde vocal**. Aquecer é dar ao corpo uma **nova configuração muscular**, com ajustes que garantem qualidade e segurança na prática.</p>\n<p>A primeira etapa prática é a **postura**. De pé, tronco, ombros, pescoço e cabeça devem estar alinhados — a musculatura respiratória está diretamente ligada à coluna. Sentado, o cuidado é não \"afundar\" no encosto: coluna e quadril levemente afastados, pés no chão, evitando o relaxamento que compromete a respiração. A segunda etapa é o **alongamento**: pescoço e ombros estão ligados à **laringe** e às **pregas vocais**, e precisam estar livres de tensões. A automassagem do **esternocleidomastóideo** — músculo postural também recrutado na respiração — deve ser leve e lenta: **dor é sinal de tensão**, e forçar produz o efeito contrário. Seguem-se movimentos de cabeça (\"sim\", \"não\", inclinações e rotações) e o giro de ombros para trás, que já conduz o corpo à postura de canto.</p>",
          "proseRaw": "Nesta aula, a professora Paula Santana apresenta o **aquecimento vocal** como etapa indispensável — e propõe que o aluno pense em **aquecimento corporal e vocal**, pois o instrumento do cantor é o próprio corpo. Assim como um atleta prepara o corpo antes do esforço, o cantor é um **atleta da voz**: cantar exige que musculaturas, tecidos e ligamentos trabalhem de forma mais intensa e coordenada.\n\nO **objetivo geral** do aquecimento é preparar as estruturas fisiológicas para a voz cantada. Dele derivam objetivos específicos: aumentar **energia muscular e respiratória**, **circulação sanguínea** e **oxigenação**, equilibrar o **fluxo de ar** e, sobretudo, manter a **saúde vocal**. Aquecer é dar ao corpo uma **nova configuração muscular**, com ajustes que garantem qualidade e segurança na prática.\n\nA primeira etapa prática é a **postura**. De pé, tronco, ombros, pescoço e cabeça devem estar alinhados — a musculatura respiratória está diretamente ligada à coluna. Sentado, o cuidado é não \"afundar\" no encosto: coluna e quadril levemente afastados, pés no chão, evitando o relaxamento que compromete a respiração. A segunda etapa é o **alongamento**: pescoço e ombros estão ligados à **laringe** e às **pregas vocais**, e precisam estar livres de tensões. A automassagem do **esternocleidomastóideo** — músculo postural também recrutado na respiração — deve ser leve e lenta: **dor é sinal de tensão**, e forçar produz o efeito contrário. Seguem-se movimentos de cabeça (\"sim\", \"não\", inclinações e rotações) e o giro de ombros para trás, que já conduz o corpo à postura de canto.",
          "notas": "- A aula é **Parte I**: o **desaquecimento vocal** é anunciado na abertura como igualmente importante, mas o conteúdo prático aqui se concentra no aquecimento (postura + alongamento). Articular com a Parte II na sequência do módulo.\n- A aula é **prática e guiada**: incentivar o aluno a executar os exercícios junto com o vídeo, idealmente em frente a um espelho (sugestão feita pela própria instrutora).\n- Reforçar a **regra de segurança**: movimentos lentos, sem força; interromper se houver dor.\n- Conexões com o curso: retoma **postura corporal** (Módulo 2), **subsistemas** (Módulo 3) e antecipa o trabalho de **musculatura do trato vocal** (Módulo 5) — a instrutora explicita que pescoço livre reflete em bom funcionamento dos articuladores.",
