          "prose": "<p>O **tubo de ressonância**, popularmente conhecido como **laxvox** (nome de uma marca que virou sinônimo do dispositivo), é um recurso para exercícios de **trato vocal semi-ocluído** — ou seja, exercícios em que a saída do ar, da laringe aos lábios, fica \"meio fechada\". Essa condição favorece a **interação entre a fonte do som** (laringe e pregas vocais) **e o filtro** (trato vocal, articuladores e cavidades de ressonância), resultando em fonação com **menor esforço, menor impacto e menos tensão muscular** — e, por consequência, menos **quebras vocais**.</p>\n<p>Na prática, o tubo é inserido numa **garrafa com água até a metade**. A **profundidade do tubo na água determina a demanda**: a professora demonstra com **dois centímetros** e explica que, quanto mais fundo, maior a intensidade do trabalho muscular. Ao cantar dentro do tubo, a onda sonora produz **bolhas na água**, e esse trabalho \"retorna\" ao trato vocal, **ampliando-o** e promovendo um efeito de **massagem e relaxamento** das estruturas — por isso o recurso é tão indicado para **aquecimento vocal** e para cantar a melodia do repertório dentro do tubo.</p>\n<p>A execução exige cuidados: as **bolhas devem ser constantes**, pois refletem um **fluxo de som contínuo**; é preciso **respirar bem e manter o apoio** (expansão do diafragma, elevação das costelas); os **lábios ficam na forma da vogal U**, sem projetá-los para dentro (o que geraria tensão); e a instrução central é **cantar, não soprar** — soprar apenas joga ar no tubo, sem o efeito técnico desejado. A aula propõe uma sequência progressiva: **nota sustentada**, **melodia em terças**, **oitavas** (elasticidade e mobilidade laríngea) e **segundas** (agilidade), além do trabalho das **extensões grave e aguda** — a professora, que é **soprano**, exemplifica usando o laxvox para desenvolver facilidade na sua **região grave**.</p>",
          "proseRaw": "O **tubo de ressonância**, popularmente conhecido como **laxvox** (nome de uma marca que virou sinônimo do dispositivo), é um recurso para exercícios de **trato vocal semi-ocluído** — ou seja, exercícios em que a saída do ar, da laringe aos lábios, fica \"meio fechada\". Essa condição favorece a **interação entre a fonte do som** (laringe e pregas vocais) **e o filtro** (trato vocal, articuladores e cavidades de ressonância), resultando em fonação com **menor esforço, menor impacto e menos tensão muscular** — e, por consequência, menos **quebras vocais**.\n\nNa prática, o tubo é inserido numa **garrafa com água até a metade**. A **profundidade do tubo na água determina a demanda**: a professora demonstra com **dois centímetros** e explica que, quanto mais fundo, maior a intensidade do trabalho muscular. Ao cantar dentro do tubo, a onda sonora produz **bolhas na água**, e esse trabalho \"retorna\" ao trato vocal, **ampliando-o** e promovendo um efeito de **massagem e relaxamento** das estruturas — por isso o recurso é tão indicado para **aquecimento vocal** e para cantar a melodia do repertório dentro do tubo.\n\nA execução exige cuidados: as **bolhas devem ser constantes**, pois refletem um **fluxo de som contínuo**; é preciso **respirar bem e manter o apoio** (expansão do diafragma, elevação das costelas); os **lábios ficam na forma da vogal U**, sem projetá-los para dentro (o que geraria tensão); e a instrução central é **cantar, não soprar** — soprar apenas joga ar no tubo, sem o efeito técnico desejado. A aula propõe uma sequência progressiva: **nota sustentada**, **melodia em terças**, **oitavas** (elasticidade e mobilidade laríngea) e **segundas** (agilidade), além do trabalho das **extensões grave e aguda** — a professora, que é **soprano**, exemplifica usando o laxvox para desenvolver facilidade na sua **região grave**.",
          "notas": "- **Pré-requisitos naturais:** a aula pressupõe o **apoio respiratório** (Módulo 2) e o modelo **fonte–filtro** (Módulo 3), ambos explicitamente evocados na explicação.\n- **Ponte com repertório:** a sugestão de cantar a melodia do louvor dentro do tubo conecta esta aula ao módulo de aplicação em hinos.\n- **Ponto de atenção para o aluno:** reforçar que a constância das bolhas é um **biofeedback** simples e observável da estabilidade da emissão.",
