          "prose": "<p>A aula parte de uma premissa já construída no curso: diferente do tecladista ou do violinista, o cantor tem seu **instrumento dentro do próprio corpo** — e, por isso, \"ninguém é feliz sozinho\". A saúde vocal não depende apenas de técnica, mas de uma **rede de profissionais** que mantém o instrumento funcionando.</p>\n<p>O primeiro parceiro é o **otorrino**, responsável por avaliar pregas vocais, vias respiratórias e audição. A professora recomenda a **videolaringoscopia** ao menos uma vez por ano — e cita a **videolaringoestroboscopia**, exame de imagem mais refinada que mostra nitidamente os movimentos das pregas vocais, permitindo detectar **lesões ou fendas** precocemente.</p>\n<p>Com o laudo em mãos, entra o **fonoaudiólogo**: além de reabilitar a voz lesionada, ele trabalha **fortalecimento muscular, dicção, musculatura orofacial, suporte respiratório e padrões de voz** (rouquidão, voz pesada etc.). Na participação especial, uma fonoaudióloga apresenta um **checklist de sinais** — rouquidão frequente, desconforto após uso intenso, limitação em agudos ou graves, ofegância, disfunção temporomandibular — que indicam a necessidade de **fonoterapia**.</p>\n<p>A aula segue pelo **gastroenterologista** (o **refluxo** causa limitações nas pregas vocais e pode gerar lesões), pelo **dentista** (o **bruxismo** compromete a musculatura orofacial e reflete na qualidade vocal), pelo **fisioterapeuta** (**postura corporal** alinhada no canto e no dia a dia), pelo **educador físico** (atividade física gera energia corporal e **musculaturas respiratórias tonificadas**) e pelo **nutricionista** (cuidar da alimentação, sobretudo perto de cantar, evitando **pigarro** e saliva espessa).</p>\n<p>O fechamento amarra a rede: o **professor de canto** frequentemente identifica na aula problemas que não resolve sozinho — refluxo, coluna, bruxismo, desvio de septo — e encaminha o aluno aos demais profissionais. Com um \"material saudável\", ele pode então desenvolver técnica, **performance, interpretação e musicalidade**. A mensagem final é a **longevidade vocal**: a voz é o resultado de um corpo inteiro saudável, e cuidar dela é cuidar do todo.</p>",
          "proseRaw": "A aula parte de uma premissa já construída no curso: diferente do tecladista ou do violinista, o cantor tem seu **instrumento dentro do próprio corpo** — e, por isso, \"ninguém é feliz sozinho\". A saúde vocal não depende apenas de técnica, mas de uma **rede de profissionais** que mantém o instrumento funcionando.\n\nO primeiro parceiro é o **otorrino**, responsável por avaliar pregas vocais, vias respiratórias e audição. A professora recomenda a **videolaringoscopia** ao menos uma vez por ano — e cita a **videolaringoestroboscopia**, exame de imagem mais refinada que mostra nitidamente os movimentos das pregas vocais, permitindo detectar **lesões ou fendas** precocemente.\n\nCom o laudo em mãos, entra o **fonoaudiólogo**: além de reabilitar a voz lesionada, ele trabalha **fortalecimento muscular, dicção, musculatura orofacial, suporte respiratório e padrões de voz** (rouquidão, voz pesada etc.). Na participação especial, uma fonoaudióloga apresenta um **checklist de sinais** — rouquidão frequente, desconforto após uso intenso, limitação em agudos ou graves, ofegância, disfunção temporomandibular — que indicam a necessidade de **fonoterapia**.\n\nA aula segue pelo **gastroenterologista** (o **refluxo** causa limitações nas pregas vocais e pode gerar lesões), pelo **dentista** (o **bruxismo** compromete a musculatura orofacial e reflete na qualidade vocal), pelo **fisioterapeuta** (**postura corporal** alinhada no canto e no dia a dia), pelo **educador físico** (atividade física gera energia corporal e **musculaturas respiratórias tonificadas**) e pelo **nutricionista** (cuidar da alimentação, sobretudo perto de cantar, evitando **pigarro** e saliva espessa).\n\nO fechamento amarra a rede: o **professor de canto** frequentemente identifica na aula problemas que não resolve sozinho — refluxo, coluna, bruxismo, desvio de septo — e encaminha o aluno aos demais profissionais. Com um \"material saudável\", ele pode então desenvolver técnica, **performance, interpretação e musicalidade**. A mensagem final é a **longevidade vocal**: a voz é o resultado de um corpo inteiro saudável, e cuidar dela é cuidar do todo.",
          "notas": "- Aula de **caráter orientativo/preventivo**, sem exercícios práticos; funciona como consolidação do princípio \"corpo-instrumento\" do Módulo 1 e complementa os temas de postura (Módulo 2) e musculatura (Módulo 5).\n- Sugestão de uso: propor ao aluno que monte seu **\"mapa de cuidado vocal\"** pessoal, verificando quais profissionais já consulta e quais sinais do checklist reconhece em si.",
