          "prose": "<p>Esta aula transpõe a técnica vocal para a **prática do ministério de louvor**: o que fazer quando uma pessoa nova entra no grupo. A professora propõe o momento da **audição** — que aqui não tem caráter eliminatório, mas diagnóstico: trata-se de **ouvir a voz** para conhecer suas características e inserir o cantor no **naipe** mais adequado, para o bem dele e do coral.</p>\n<p>O primeiro critério é o **nível técnico** do novo integrante: quem já tem domínio vocal será ouvido de um modo; quem não tem, precisa de acolhimento e até de auxílio durante os exercícios (por exemplo, orientar a **abertura do espaço na cavidade oral** nas notas agudas). Em seguida, dois exercícios de sondagem: a sequência de **vogais I–E–A–O–U**, descendo do agudo ao grave, revela a **qualidade articulatória**; o **arpejo com vogal U** — que alonga o trato vocal e ajuda a descer a laringe — mostra o **manejo da extensão**.</p>\n<p>Dois alertas técnicos importantes: (1) todo naipe precisa das duas regiões — **sopranos com bons graves, contraltos e baixos com bons agudos** — porque o coral canta em **uníssono** em regiões variadas; (2) a audição **não é o momento de expandir a extensão**: esse trabalho fisiológico pertence ao **profissional da voz**. Por fim, a escolha do repertório deve ser estratégica: hinos como *Encontrei o Grande Amor* e *Aleluia, Muitas Vozes de Anjo* exigem grave e agudo no mesmo louvor, revelando a voz inteira do cantor. E como a voz está em **constante evolução**, essa escuta deve ser refeita periodicamente, inclusive com os membros antigos.</p>",
          "proseRaw": "Esta aula transpõe a técnica vocal para a **prática do ministério de louvor**: o que fazer quando uma pessoa nova entra no grupo. A professora propõe o momento da **audição** — que aqui não tem caráter eliminatório, mas diagnóstico: trata-se de **ouvir a voz** para conhecer suas características e inserir o cantor no **naipe** mais adequado, para o bem dele e do coral.\n\nO primeiro critério é o **nível técnico** do novo integrante: quem já tem domínio vocal será ouvido de um modo; quem não tem, precisa de acolhimento e até de auxílio durante os exercícios (por exemplo, orientar a **abertura do espaço na cavidade oral** nas notas agudas). Em seguida, dois exercícios de sondagem: a sequência de **vogais I–E–A–O–U**, descendo do agudo ao grave, revela a **qualidade articulatória**; o **arpejo com vogal U** — que alonga o trato vocal e ajuda a descer a laringe — mostra o **manejo da extensão**.\n\nDois alertas técnicos importantes: (1) todo naipe precisa das duas regiões — **sopranos com bons graves, contraltos e baixos com bons agudos** — porque o coral canta em **uníssono** em regiões variadas; (2) a audição **não é o momento de expandir a extensão**: esse trabalho fisiológico pertence ao **profissional da voz**. Por fim, a escolha do repertório deve ser estratégica: hinos como *Encontrei o Grande Amor* e *Aleluia, Muitas Vozes de Anjo* exigem grave e agudo no mesmo louvor, revelando a voz inteira do cantor. E como a voz está em **constante evolução**, essa escuta deve ser refeita periodicamente, inclusive com os membros antigos.",
          "notas": "- Aula de **aplicação prática**: pressupõe os conteúdos de vogais, extensão, tessitura e naipes — ideal posicioná-la após os módulos de registros/extensão e de vogais/consoantes.\n- Conecta-se às aulas de análise de repertório (os hinos citados foram estudados em aulas anteriores).\n- Útil também para **regentes e coordenadores de louvor**, não apenas cantores.",
