          "prose": "<p>A professora abre a aula avisando que o tema é diferente, mas **completamente inserido no estudo do canto**: começa ali a **teoria musical**, em ritmo calmo, para quem nunca leu uma partitura. A música é apresentada como **arte e linguagem universal**, que absorve culturas, idiomas e períodos históricos — e a **coletânea de partituras** da igreja é apontada como o recurso concreto que tornará o estudo dos louvores \"ainda mais completo\".</p>\n<p>A escrita musical acontece sobre a **pauta**, também chamada **pentagrama**: **cinco linhas e quatro espaços**, sempre contados **de baixo para cima**. Quando a melodia ultrapassa esse espaço — notas muito agudas ou muito graves —, entram as **linhas e espaços suplementares** (superiores e inferiores). Na horizontal, a pauta é dividida por **barras**, que separam a música em **compassos**, geralmente numerados no início de cada um.</p>\n<p>Em seguida, entram as **sete notas** — Dó, Ré, Mi, Fá, Sol, Lá, Si — associadas às **teclas brancas do teclado**, repetindo-se na **oitava**. Para saber *qual nota está em qual posição*, é preciso uma referência: a **clave**. Ela é o símbolo colocado no início da pauta, e a linha onde seu desenho se inicia recebe o nome da própria clave. Na **clave de Sol** (2ª linha), a 2ª linha é Sol; daí se deduz toda a escada: Lá no 2º espaço, Si na 3ª linha e, descendo, Fá no 1º espaço, Mi na 1ª linha, Ré e Dó nos suplementares inferiores. Na **clave de Fá** (4ª linha), toda a disposição muda: a mesma nota ocupa posições diferentes conforme a clave que orienta a leitura.</p>\n<p>Por fim, as notas ganham duração por meio das **figuras musicais**: **semibreve, mínima, semínima, colcheia, semicolcheia, fusa e semifusa** — diferenciadas por cabeça, haste e colchetes. Cada figura de som tem sua **pausa** (figura de silêncio) equivalente: a pausa da semibreve fica pendurada **embaixo da 4ª linha**, a da mínima assentada **sobre a 3ª linha**, e as demais acompanham o número de colchetes. Nos valores: **semibreve = 4 tempos**, **mínima = 2**, **semínima = 1** — por isso quatro semínimas equivalem a uma semibreve.</p>",
          "proseRaw": "A professora abre a aula avisando que o tema é diferente, mas **completamente inserido no estudo do canto**: começa ali a **teoria musical**, em ritmo calmo, para quem nunca leu uma partitura. A música é apresentada como **arte e linguagem universal**, que absorve culturas, idiomas e períodos históricos — e a **coletânea de partituras** da igreja é apontada como o recurso concreto que tornará o estudo dos louvores \"ainda mais completo\".\n\nA escrita musical acontece sobre a **pauta**, também chamada **pentagrama**: **cinco linhas e quatro espaços**, sempre contados **de baixo para cima**. Quando a melodia ultrapassa esse espaço — notas muito agudas ou muito graves —, entram as **linhas e espaços suplementares** (superiores e inferiores). Na horizontal, a pauta é dividida por **barras**, que separam a música em **compassos**, geralmente numerados no início de cada um.\n\nEm seguida, entram as **sete notas** — Dó, Ré, Mi, Fá, Sol, Lá, Si — associadas às **teclas brancas do teclado**, repetindo-se na **oitava**. Para saber *qual nota está em qual posição*, é preciso uma referência: a **clave**. Ela é o símbolo colocado no início da pauta, e a linha onde seu desenho se inicia recebe o nome da própria clave. Na **clave de Sol** (2ª linha), a 2ª linha é Sol; daí se deduz toda a escada: Lá no 2º espaço, Si na 3ª linha e, descendo, Fá no 1º espaço, Mi na 1ª linha, Ré e Dó nos suplementares inferiores. Na **clave de Fá** (4ª linha), toda a disposição muda: a mesma nota ocupa posições diferentes conforme a clave que orienta a leitura.\n\nPor fim, as notas ganham duração por meio das **figuras musicais**: **semibreve, mínima, semínima, colcheia, semicolcheia, fusa e semifusa** — diferenciadas por cabeça, haste e colchetes. Cada figura de som tem sua **pausa** (figura de silêncio) equivalente: a pausa da semibreve fica pendurada **embaixo da 4ª linha**, a da mínima assentada **sobre a 3ª linha**, e as demais acompanham o número de colchetes. Nos valores: **semibreve = 4 tempos**, **mínima = 2**, **semínima = 1** — por isso quatro semínimas equivalem a uma semibreve.",
          "notas": "- **Pré-requisito zero:** a aula pressupõe apenas os conceitos de grave/agudo já trabalhados no curso; o vocabulário fisiológico dos módulos anteriores não é exigido.\n- A própria instrutora sinaliza que o tema é **seriado** (\"vamos ver nas próximas aulas\"): esta aula cobre pauta, claves e figuras; **tempo/andamento** é apenas introduzido e fica para depois.\n- A transcrição fornecida **termina truncada** na comparação de valores das figuras — evitar afirmar conteúdo além da equivalência semibreve/mínima/semínima.\n- Sugestão de prática: o aluno pode abrir a coletânea de partituras e localizar clave, barras de compasso e a nota Sol (ou Fá) na pauta, conforme a demonstração.\n- Conexão pedagógica: esta aula inaugura o eixo de **leitura musical**, complementar ao eixo de técnica vocal dos Módulos 1–6.",
