          "prose": "<p>Nesta aula de repertório, a professora Paula Santana mostra como **a partitura é um mapa técnico**: cada indicação — *doltíssimo*, *expressivo*, *MF*, *grandioso* — corresponde a uma decisão fisiológica concreta. Na primeira estrofe, a **melodia grave** dispensa grandes espaços internos, mas exige **articulação precisa**; o uso da **musculatura facial** tem função física (define o texto e auxilia o arqueamento do **palato mole**), e não apenas interpretativa. Os homens devem manter a mesma embocadura e colocação ao entrar, preservando a unidade do louvor — *expressivo* significa **firme e refinado**, nunca bruto. Conforme a melodia ascende (\"sai da escuridão\", \"pensas estar só\"), o corpo responde com **embocadura mais aberta**, **apoio respiratório** para linhas longas e sutileza nos **crescendos e decrescendos** dentro da mesma sílaba. No coro *grandioso*, **postura e respiração ativa** sustentam o ápice — o modo de respirar já carrega a intenção da frase. A aula fecha distinguindo o estudo de **limpeza** (notas e ritmo por naipe) do trabalho **interpretativo**, que aqui é conduzido em bloco, unindo as dimensões **física, técnica, musical e espiritual**.</p>",
          "proseRaw": "Nesta aula de repertório, a professora Paula Santana mostra como **a partitura é um mapa técnico**: cada indicação — *doltíssimo*, *expressivo*, *MF*, *grandioso* — corresponde a uma decisão fisiológica concreta. Na primeira estrofe, a **melodia grave** dispensa grandes espaços internos, mas exige **articulação precisa**; o uso da **musculatura facial** tem função física (define o texto e auxilia o arqueamento do **palato mole**), e não apenas interpretativa. Os homens devem manter a mesma embocadura e colocação ao entrar, preservando a unidade do louvor — *expressivo* significa **firme e refinado**, nunca bruto. Conforme a melodia ascende (\"sai da escuridão\", \"pensas estar só\"), o corpo responde com **embocadura mais aberta**, **apoio respiratório** para linhas longas e sutileza nos **crescendos e decrescendos** dentro da mesma sílaba. No coro *grandioso*, **postura e respiração ativa** sustentam o ápice — o modo de respirar já carrega a intenção da frase. A aula fecha distinguindo o estudo de **limpeza** (notas e ritmo por naipe) do trabalho **interpretativo**, que aqui é conduzido em bloco, unindo as dimensões **física, técnica, musical e espiritual**.",
