          "orderInMod": 6,
          "title": "Aula — Nasalidade: equilíbrio entre cavidade oral e nasal",
          "date": "2025-01-18",
          "videoId": "LLZ7eD07YGo",
          "type": "repertorio",
          "duration": "30 min",
          "image": "/assets/fig-06-valvula.png",
          "imageCaption": "Véu do palato como válvula entre as cavidades oral e nasal",
          "objetivos": [
            "Compreender o que é a **nasalidade**, por que ela surge como **compensação** do trato vocal e quando é recurso estilístico × quando é excesso a corrigir.",
            "Distinguir **som metálico** (brilho/projeção) de **nasalidade** (desequilíbrio de ressonância).",
            "Desenvolver a percepção interna dos **moldes do trato vocal** e da distribuição do som entre **cavidade oral** e **cavidade nasal**.",
            "Executar exercícios corretivos: teste do **nariz tampado**, bochechas infladas com palma na boca, **vibrantes** (língua e lábio) e **fricativas Z, J, V** — sempre com leveza e fluxo de ar contínuo."
          ],
          "topicos": [
            "Nasalidade como compensação; redistribuição do som nas cavidades de amplificação",
            "Revisão dos **articuladores** e da sensação de abertura interna (véu do palato, faringe, laringe, base da língua)",
            "Sons naturalmente nasais do português (N, M, semivogais) × excesso de nasalidade",
            "**Som metálico × nasalidade**: uso funcional da cavidade nasal sem disfunção",
            "Exercícios: nariz tampado; bochecha de \"sapo\" + palma da mão com vogal **A**; vibração de língua e de lábio com vogal **U** e saltos de oitava; **sobrancelha erguida** ativando o **palato mole**; fricativas **Z, J, V** com agilidade e acesso a graves sem esforço (a professora, soprano, relata alcançar **Eb2**)"
          ],
          "timestamps": [
            {
              "sec": 0,
              "time": "00:00",
              "label": "O que é nasalidade e as compensações do trato vocal"
            },
            {
              "sec": 0,
              "time": "00:00",
              "label": "Exercício com nariz tampado: som sustentado na cavidade oral"
            },
            {
              "sec": 0,
              "time": "00:00",
              "label": "Som metálico × nasalidade"
            },
            {
              "sec": 0,
              "time": "00:00",
              "label": "Vibrantes (língua e lábio): impossíveis de nasalizar"
            },
            {
              "sec": 0,
              "time": "00:00",
              "label": "Sobrancelha erguida no agudo eleva o palato mole"
            },
            {
              "sec": 0,
              "time": "00:00",
              "label": "Fricativas Z, J, V: adução equilibrada e graves sem esforço"
            }
          ],
          "prose": "<p>A **nasalidade** pode existir na voz sem que o cantor perceba. Quando há alguma disfunção na **utilização da voz no trato vocal**, o organismo faz **compensações** — e uma das mais comuns é deslocar o som em excesso para a **cavidade nasal**. A solução não é eliminar o nariz do processo (sons como **N** e **M** são naturalmente nasais no português), mas **redistribuir o som** entre as cavidades de amplificação com equilíbrio. Registro importante da aula: dependendo do estilo musical, a nasalidade pode ser **bem-vinda**; o que traz prejuízo é o **excesso**.</p>\n<p>Antes da prática, a professora retoma os **moldes do trato vocal** e os **articuladores** (lábios, língua, dentes, mandíbula, palato mole, faringe, laringe), conduzindo o aluno a *sentir* o que não consegue ver: na inspiração nasal, o **véu do palato** abre, a **faringe** expande, a **laringe** desce e a **base da língua** desce junto. Surge aqui uma distinção teórica valiosa: **som metálico não é nasalidade**. O metal é o brilho de uma voz projetada que *aproveita* a cavidade nasal como recurso, sem disfunção; a nasalidade excessiva é desequilíbrio a reajustar.</p>\n<p>A sequência prática é progressiva: (1) **nariz tampado** — o som deve continuar compreensível e sustentado na cavidade oral; (2) **bochechas infladas** (\"sapo de bochechinha\") e vogal **A** com a **palma da mão tapando a boca**, mantendo o interior ampliado e a língua relaxada, sem dorso alto; (3) **vibrantes** — vibração de **língua** e de **lábio** — que por natureza não admitem nasalidade, trabalhados na forma da vogal **U**, com saltos de **oitava** e **sobrancelha erguida** no agudo (gesto que eleva o **palato mole** e treina coordenação motora da musculatura facial); (4) fricativas **Z, J, V**, que também impedem o som nasal, promovem **fechamento equilibrado das pregas vocais** e facilitam o acesso aos graves — a professora, soprano, chega a um **Eb2** sem esforço. O princípio que atravessa tudo: **fluxo de ar contínuo, espaços abertos, nunca força** — agudo não se faz com pressão, e excesso de ar estressa a prega vocal.</p>",
          "proseRaw": "A **nasalidade** pode existir na voz sem que o cantor perceba. Quando há alguma disfunção na **utilização da voz no trato vocal**, o organismo faz **compensações** — e uma das mais comuns é deslocar o som em excesso para a **cavidade nasal**. A solução não é eliminar o nariz do processo (sons como **N** e **M** são naturalmente nasais no português), mas **redistribuir o som** entre as cavidades de amplificação com equilíbrio. Registro importante da aula: dependendo do estilo musical, a nasalidade pode ser **bem-vinda**; o que traz prejuízo é o **excesso**.\n\nAntes da prática, a professora retoma os **moldes do trato vocal** e os **articuladores** (lábios, língua, dentes, mandíbula, palato mole, faringe, laringe), conduzindo o aluno a *sentir* o que não consegue ver: na inspiração nasal, o **véu do palato** abre, a **faringe** expande, a **laringe** desce e a **base da língua** desce junto. Surge aqui uma distinção teórica valiosa: **som metálico não é nasalidade**. O metal é o brilho de uma voz projetada que *aproveita* a cavidade nasal como recurso, sem disfunção; a nasalidade excessiva é desequilíbrio a reajustar.\n\nA sequência prática é progressiva: (1) **nariz tampado** — o som deve continuar compreensível e sustentado na cavidade oral; (2) **bochechas infladas** (\"sapo de bochechinha\") e vogal **A** com a **palma da mão tapando a boca**, mantendo o interior ampliado e a língua relaxada, sem dorso alto; (3) **vibrantes** — vibração de **língua** e de **lábio** — que por natureza não admitem nasalidade, trabalhados na forma da vogal **U**, com saltos de **oitava** e **sobrancelha erguida** no agudo (gesto que eleva o **palato mole** e treina coordenação motora da musculatura facial); (4) fricativas **Z, J, V**, que também impedem o som nasal, promovem **fechamento equilibrado das pregas vocais** e facilitam o acesso aos graves — a professora, soprano, chega a um **Eb2** sem esforço. O princípio que atravessa tudo: **fluxo de ar contínuo, espaços abertos, nunca força** — agudo não se faz com pressão, e excesso de ar estressa a prega vocal.",
          "notas": "- **Pré-requisitos citados pela própria professora:** aulas de **articuladores** e de **musculatura facial** (ver Módulo 5 do mapa).\n- Conexão com o Módulo 2: a exigência de **fluxo de ar contínuo sem pressão** pressupõe o apoio/suporte já treinado.\n- Alerta técnico recorrente: na vibração de lábio, manter os **dentes levemente separados** para não compensar com força na mandíbula/arcada dentária.",
          "exercicios": "Prática vocal e exercícios específicos ministrados pela Prof.ª Paula Santana para o Módulo 8."
