          "prose": "<p>Nesta primeira de duas aulas sobre **articulação vocálica**, a professora Paula Santana parte de um princípio simples e decisivo: **o canto é um ato vocálico**. Se retirarmos as consoantes de um texto, ainda é possível cantá-lo; se retirarmos as vogais, o canto desaparece. Isso porque as **vogais são os moldes** que o **trato vocal** executa — formas montadas pelos **articuladores** (língua, lábios, palato mole, musculatura facial) que garantem **fluxo de ar e som contínuos**, sem obstrução.</p>\n<p>A aula contrasta a **fala**, aprendida desde a infância e realizada de forma **automática**, com o **canto**, que exige **consciência e intencionalidade** em cada gesto articulatório. Por isso, o treino começa na fala — a sequência **A-E-I-O-U** diante do espelho, com o rosto em movimento (lábios, zigomáticos, bucinador, orbicular) — e progride para o canto em **nota única**, onde a meta é a **fluidez**: nada de \"rearticular\" cada vogal com excesso, mas deixar o som **contínuo**, como em *legato*.</p>\n<p>Em seguida, o exercício ganha **intervalos de duas notas por vogal** (sequência I-E-A-O-U), e a aluna/o é convidada a perceber que a mudança de altura **não é um movimento isolado das pregas vocais**, mas também um **movimento articulatório**. A professora reforça ainda que **mover o corpo** (como o gesto da mão acompanhando o som) **ajuda neurologicamente** a projeção e a organização do canto — não é estética, é função.</p>\n<p>Na aplicação ao repertório, a frase **\"Jesus, o amigo incomparável\"** (louvor da aula seguinte) é decomposta em suas vogais, introduzindo o conceito de **semivogal** (sons como o de *N* em \"incomparável\" e certos *L*, que não obstruem o ar). Por fim, vocalizes por vogal mostram que **uma mesma vogal não tem a mesma forma no grave e no agudo**: o trato vocal realiza **ajustes** (subir o palato, descer a língua, abrir os lábios) para **projetar o som** em toda a extensão. A aula termina com um exercício integrador: todas as vogais em **uma só respiração**, com frase fluido e contínuo.</p>",
          "proseRaw": "Nesta primeira de duas aulas sobre **articulação vocálica**, a professora Paula Santana parte de um princípio simples e decisivo: **o canto é um ato vocálico**. Se retirarmos as consoantes de um texto, ainda é possível cantá-lo; se retirarmos as vogais, o canto desaparece. Isso porque as **vogais são os moldes** que o **trato vocal** executa — formas montadas pelos **articuladores** (língua, lábios, palato mole, musculatura facial) que garantem **fluxo de ar e som contínuos**, sem obstrução.\n\nA aula contrasta a **fala**, aprendida desde a infância e realizada de forma **automática**, com o **canto**, que exige **consciência e intencionalidade** em cada gesto articulatório. Por isso, o treino começa na fala — a sequência **A-E-I-O-U** diante do espelho, com o rosto em movimento (lábios, zigomáticos, bucinador, orbicular) — e progride para o canto em **nota única**, onde a meta é a **fluidez**: nada de \"rearticular\" cada vogal com excesso, mas deixar o som **contínuo**, como em *legato*.\n\nEm seguida, o exercício ganha **intervalos de duas notas por vogal** (sequência I-E-A-O-U), e a aluna/o é convidada a perceber que a mudança de altura **não é um movimento isolado das pregas vocais**, mas também um **movimento articulatório**. A professora reforça ainda que **mover o corpo** (como o gesto da mão acompanhando o som) **ajuda neurologicamente** a projeção e a organização do canto — não é estética, é função.\n\nNa aplicação ao repertório, a frase **\"Jesus, o amigo incomparável\"** (louvor da aula seguinte) é decomposta em suas vogais, introduzindo o conceito de **semivogal** (sons como o de *N* em \"incomparável\" e certos *L*, que não obstruem o ar). Por fim, vocalizes por vogal mostram que **uma mesma vogal não tem a mesma forma no grave e no agudo**: o trato vocal realiza **ajustes** (subir o palato, descer a língua, abrir os lábios) para **projetar o som** em toda a extensão. A aula termina com um exercício integrador: todas as vogais em **uma só respiração**, com frase fluido e contínuo.",
          "notas": "- **Pré-requisitos:** a própria instrutora recomenda ter assistido às aulas anteriores; idealmente, o aluno já passou pelos módulos de respiração/apoio (Módulo 2), trato vocal e articuladores (Módulos 3 e 5) e pela Aula 12 de vogais (Módulo 6).\n- **Aula mais curta e prática:** foi planejada para ser **reassistida durante a semana** como treino guiado; incentivar a prática diária em frente ao espelho.\n- **Ponte direta** com a aula seguinte (repertório \"Jesus, o amigo incomparável\"), que aplica este mesmo tema — convém manter as duas sequenciadas na ementa.\n- **Cuidado com o exagero:** o ponto crítico do exercício é a fluidez — observar alunos que \"mastigam\" as vogais ou tensionam a mandíbula a cada troca.",
