          "prose": "<p>Nesta aula de repertório, a **articulação vocálica** deixa de ser exercício isolado e vira ferramenta de comunicação no culto. A instrutora parte de um princípio: o cantor sempre transmite uma **mensagem** — e um visitante que entra na igreja pela primeira vez só compreenderá texto, contexto e intenção se a dicção estiver clara, da nota mais grave à mais aguda.</p>\n<p>O método prático é progressivo: canta-se cada frase **somente com as vogais** (admitindo as **semivogais** M, N, L), eliminando as **consoantes obstrutivas** que interrompem o fluxo de ar. Sem as consoantes, as falhas aparecem — trocas como IN com som de E ou ON com som de U revelam onde o **trato vocal** precisa de refinamento. Em seguida, o texto completo é reintroduzido **mantendo o mesmo padrão articulatório**, o que melhora também **afinação** e **fraseado**.</p>\n<p>No refrão, o foco muda para a **ressonância**: \"então, enfim, verei\" concentra sons nasais que, sem boa movimentação vocálica, \"caem\" na cavidade nasal — a saída é abrir o **espaço de oralidade**. A frase completa exige **respiração e apoio diafragmático** para sustentar os ajustes vocálicos. Só depois de refinada a clareza é que se entra no trabalho de **interpretação** — melódica, textual e espiritual —, definindo quanto som se põe ou se tira em cada frase.</p>",
          "proseRaw": "Nesta aula de repertório, a **articulação vocálica** deixa de ser exercício isolado e vira ferramenta de comunicação no culto. A instrutora parte de um princípio: o cantor sempre transmite uma **mensagem** — e um visitante que entra na igreja pela primeira vez só compreenderá texto, contexto e intenção se a dicção estiver clara, da nota mais grave à mais aguda.\n\nO método prático é progressivo: canta-se cada frase **somente com as vogais** (admitindo as **semivogais** M, N, L), eliminando as **consoantes obstrutivas** que interrompem o fluxo de ar. Sem as consoantes, as falhas aparecem — trocas como IN com som de E ou ON com som de U revelam onde o **trato vocal** precisa de refinamento. Em seguida, o texto completo é reintroduzido **mantendo o mesmo padrão articulatório**, o que melhora também **afinação** e **fraseado**.\n\nNo refrão, o foco muda para a **ressonância**: \"então, enfim, verei\" concentra sons nasais que, sem boa movimentação vocálica, \"caem\" na cavidade nasal — a saída é abrir o **espaço de oralidade**. A frase completa exige **respiração e apoio diafragmático** para sustentar os ajustes vocálicos. Só depois de refinada a clareza é que se entra no trabalho de **interpretação** — melódica, textual e espiritual —, definindo quanto som se põe ou se tira em cada frase.",
          "notas": "- **Sugestão de prática:** a instrutora recomenda reservar parte do ensaio do grupo de louvor para esse trabalho — boa atividade coletiva.\n- **Adaptação:** contraltos, tenores e baixos devem repetir o estudo na melodia escrita para sua voz (ou em coletânea sem divisão de vozes).\n- **Encadeamento:** a aula pressupõe a lição anterior de articulação vocálica e prepara o aluno para o estudo interpretativo (retomado de *\"Uma voz mansa\"*).\n- **Alerta comum:** na fala, articular é automático; no canto, exige consciência deliberada — daí a lentidão inicial ser esperada e saudável.",
