          "prose": "<p>Esta aula apresenta um **método de estudo individual** aplicável a qualquer hino do repertório. A proposta parte de uma constatação prática: no ensaio coletivo o tempo é curto, e cabe a cada cantor chegar preparado — tanto técnica quanto espiritualmente. A professora propõe três passos cumulativos.</p>\n<p>O **primeiro passo** é ler a letra e compreender a mensagem. Cantar \"no automático\", mesmo dominando notas e divisão de vozes, esvazia a transmissão do texto — e é o texto que alcança quem ouve o hino pela primeira vez no culto. O **segundo passo** é a **leitura rítmica**: falar as sílabas no tempo exato, sem melodia. No hino estudado, em **compasso 3/4**, a primeira sílaba não entra no tempo 1, mas no final do terceiro tempo — e essa precisão define *quando* cada articulador deve se mover. O **terceiro passo** é a **leitura melódica**, na qual o **trato vocal** passa a moldar o som gerado na laringe.</p>\n<p>Aqui a técnica dos módulos anteriores se concretiza: o salto ascendente até o **Si** exige ajuste articulatório consciente; o **\"um\" nasal** em região aguda pede redistribuição da ressonância, ampliando o espaço da **cavidade oral** para não \"prender\" o som no nariz; e a sílaba sobre o **tempo forte** deve receber a direção da frase. O canto, conclui a aula, é ao mesmo tempo **físico, musical e espiritual** — e o estudo individual é o que sustenta os três.</p>",
          "proseRaw": "Esta aula apresenta um **método de estudo individual** aplicável a qualquer hino do repertório. A proposta parte de uma constatação prática: no ensaio coletivo o tempo é curto, e cabe a cada cantor chegar preparado — tanto técnica quanto espiritualmente. A professora propõe três passos cumulativos.\n\nO **primeiro passo** é ler a letra e compreender a mensagem. Cantar \"no automático\", mesmo dominando notas e divisão de vozes, esvazia a transmissão do texto — e é o texto que alcança quem ouve o hino pela primeira vez no culto. O **segundo passo** é a **leitura rítmica**: falar as sílabas no tempo exato, sem melodia. No hino estudado, em **compasso 3/4**, a primeira sílaba não entra no tempo 1, mas no final do terceiro tempo — e essa precisão define *quando* cada articulador deve se mover. O **terceiro passo** é a **leitura melódica**, na qual o **trato vocal** passa a moldar o som gerado na laringe.\n\nAqui a técnica dos módulos anteriores se concretiza: o salto ascendente até o **Si** exige ajuste articulatório consciente; o **\"um\" nasal** em região aguda pede redistribuição da ressonância, ampliando o espaço da **cavidade oral** para não \"prender\" o som no nariz; e a sílaba sobre o **tempo forte** deve receber a direção da frase. O canto, conclui a aula, é ao mesmo tempo **físico, musical e espiritual** — e o estudo individual é o que sustenta os três.",
