          "prose": "<p>Esta aula inaugura uma série dedicada ao **estudo aprofundado de hinos**, aplicando cumulativamente tudo o que foi construído nos módulos anteriores — respiração, apoio, articulação, vogais e consoantes. A premissa central é que **cantar é transmitir uma mensagem**: para comunicá-la com qualidade, o cantor precisa primeiro **compreender o texto** — não apenas gramaticalmente, mas em seu **contexto** e em sua relação com a **melodia**.</p>\n<p>O hino \"Saúde Espiritual\" é lido como uma **oração**: inicia com uma indagação (\"o que direi de Ti?\"), passa pela **confissão** (\"mas hoje fraco estou, sinto saudades de Ti\") e culmina no coro como **pedido de renovo** (\"renova em mim valores Teus... saúde espiritual para com o primeiro amor Te amar\"). Diferente de hinos de exultação, este é um hino de **dependência e submissão** — e isso determina a interpretação: início **suave e solene**, sem peso nas articulações.</p>\n<p>Na prática, a instrutora conduz a **divisão silábica e rítmica** antes de cantar as notas, mostrando que as **notas estão sempre sobre as vogais**: retirando as consoantes, a linha melódica se mantém; retirando as vogais, ela desaparece. Esse exercício revela o **movimento de posição do som no trato vocal**. Em seguida, trabalha-se o **legato**, com respirações planejadas para **não cortar o sentido** das palavras — ponto essencial também para a **execução em conjunto/coro**. Por fim, a aula mostra como a articulação se adapta às regiões: a nota aguda em \"és\" pede **maior amplitude de abertura**, enquanto a região grave de \"mas hoje fraco estou\" carrega o **peso da súplica** — sempre com **respiração preparatória e apoio ativado** antes de cada frase.</p>\n<p>> **Nota didática:** a instrutora referencia a aula anterior sobre o hino \"Se as lutas da vida\" como primeiro estudo desse tipo — útil para encadeamento interno do módulo de repertório.</p>",
          "proseRaw": "Esta aula inaugura uma série dedicada ao **estudo aprofundado de hinos**, aplicando cumulativamente tudo o que foi construído nos módulos anteriores — respiração, apoio, articulação, vogais e consoantes. A premissa central é que **cantar é transmitir uma mensagem**: para comunicá-la com qualidade, o cantor precisa primeiro **compreender o texto** — não apenas gramaticalmente, mas em seu **contexto** e em sua relação com a **melodia**.\n\nO hino \"Saúde Espiritual\" é lido como uma **oração**: inicia com uma indagação (\"o que direi de Ti?\"), passa pela **confissão** (\"mas hoje fraco estou, sinto saudades de Ti\") e culmina no coro como **pedido de renovo** (\"renova em mim valores Teus... saúde espiritual para com o primeiro amor Te amar\"). Diferente de hinos de exultação, este é um hino de **dependência e submissão** — e isso determina a interpretação: início **suave e solene**, sem peso nas articulações.\n\nNa prática, a instrutora conduz a **divisão silábica e rítmica** antes de cantar as notas, mostrando que as **notas estão sempre sobre as vogais**: retirando as consoantes, a linha melódica se mantém; retirando as vogais, ela desaparece. Esse exercício revela o **movimento de posição do som no trato vocal**. Em seguida, trabalha-se o **legato**, com respirações planejadas para **não cortar o sentido** das palavras — ponto essencial também para a **execução em conjunto/coro**. Por fim, a aula mostra como a articulação se adapta às regiões: a nota aguda em \"és\" pede **maior amplitude de abertura**, enquanto a região grave de \"mas hoje fraco estou\" carrega o **peso da súplica** — sempre com **respiração preparatória e apoio ativado** antes de cada frase.\n\n> **Nota didática:** a instrutora referencia a aula anterior sobre o hino \"Se as lutas da vida\" como primeiro estudo desse tipo — útil para encadeamento interno do módulo de repertório.",
