          "prose": "<p>Esta aula inaugura a aplicação prática do **método de estudo de repertório** a um hino de **glorificação**. A instrutora reforça que, num mesmo culto, o grupo de louvor pode cantar hinos de oração, de glorificação ou sobre a volta de Jesus — e cada um exige uma **relação técnica e espiritual diferente**. Diferente do hino anterior (\"Saúde Espiritual\", de caráter solene), \"Aleluia! Muitas vozes de Anjos\" já começa com **presença e energia vocal**, o que pede atenção redobrada ao **equilíbrio do naipe**: nenhuma voz deve se destacar do conjunto.</p>\n<p>Tecnicamente, o grande desafio está na palavra **\"Aleluia\"**, que sozinha constitui uma **frase melódica** percorrendo as regiões **média, aguda e grave** — exigindo **troca de registros** controlada pelo mecanismo laríngeo, sem quebras nem deslocamentos de som. Nas frases graves, o cuidado é não adicionar **peso nem pressão de ar excessiva** (a \"voz de garganta\"); nas frases longas, a **respiração consciente** funciona como produção de energia, mantendo o **apoio ativo até a última nota**. A aula ainda detalha recursos expressivos: **crescendo** na sílaba \"le\", **intensidades diferentes** em cada repetição de \"glória\" (cada uma é uma nova afirmação de glorificação), a **musculatura facial** como veículo da mensagem e a **divisão silábica** de \"digno\", que respeita a sílaba tônica por causa do **G mudo**. O fio condutor: **técnica e música a serviço do espiritual**.</p>",
          "proseRaw": "Esta aula inaugura a aplicação prática do **método de estudo de repertório** a um hino de **glorificação**. A instrutora reforça que, num mesmo culto, o grupo de louvor pode cantar hinos de oração, de glorificação ou sobre a volta de Jesus — e cada um exige uma **relação técnica e espiritual diferente**. Diferente do hino anterior (\"Saúde Espiritual\", de caráter solene), \"Aleluia! Muitas vozes de Anjos\" já começa com **presença e energia vocal**, o que pede atenção redobrada ao **equilíbrio do naipe**: nenhuma voz deve se destacar do conjunto.\n\nTecnicamente, o grande desafio está na palavra **\"Aleluia\"**, que sozinha constitui uma **frase melódica** percorrendo as regiões **média, aguda e grave** — exigindo **troca de registros** controlada pelo mecanismo laríngeo, sem quebras nem deslocamentos de som. Nas frases graves, o cuidado é não adicionar **peso nem pressão de ar excessiva** (a \"voz de garganta\"); nas frases longas, a **respiração consciente** funciona como produção de energia, mantendo o **apoio ativo até a última nota**. A aula ainda detalha recursos expressivos: **crescendo** na sílaba \"le\", **intensidades diferentes** em cada repetição de \"glória\" (cada uma é uma nova afirmação de glorificação), a **musculatura facial** como veículo da mensagem e a **divisão silábica** de \"digno\", que respeita a sílaba tônica por causa do **G mudo**. O fio condutor: **técnica e música a serviço do espiritual**.",
