          "prose": "<p>Nesta aula, o estudo de **vogais e consoantes** sai da teoria e entra no repertório: o louvor **\"Vem, Meu Filho\"** é destrinchado frase por frase. O ponto de partida é a consciência de que a **consoante existe para obstruir** — total ou parcialmente — a passagem do som no **trato vocal**, e que cabe ao cantor impedir que essas obstruções quebrem a **linha de legato**. A justificativa é pastoral: quem está no último banco — inclusive um visitante que nunca entrou na igreja — precisa **entender o texto cantado**.</p>\n<p>O método proposto é o **treino solo-vocálico**: retiram-se todas as consoantes da frase e canta-se apenas a sequência de formas vocálicas (com as **semivogais**), para depois recolocar as consoantes **sem perder a qualidade da articulação** já montada. A abertura das **formas das vogais** é o que **minimiza o impacto das consoantes**. Na análise, consoantes **oclusivas/explosivas** como \"qu\" e \"t\" recebem atenção especial: elevam a parte central da língua e podem agravar **tensões de língua** já existentes — por isso a instrução recorrente de \"pensar na vogal que vem atrás da consoante\".</p>\n<p>A aula conecta o trabalho articulatório ao restante do curso: conhecer os **espaços das vogais** ajuda a projetar **notas agudas** (com mais espaço), a direcionar o som nas **graves**, e a executar **passagens de registro** com menos tensão, escolhendo onde usar um **modo de fonação** mais firme ou mais fluido. Por fim, há um recado direto a **contraltos e baixos**: na região grave — mais densa e próxima da fala — é comum mexer pouco a **musculatura facial**, e a linha melódica \"embola\" com facilidade; o treino articulatório é, para esses naipes, ainda mais importante.</p>",
          "proseRaw": "Nesta aula, o estudo de **vogais e consoantes** sai da teoria e entra no repertório: o louvor **\"Vem, Meu Filho\"** é destrinchado frase por frase. O ponto de partida é a consciência de que a **consoante existe para obstruir** — total ou parcialmente — a passagem do som no **trato vocal**, e que cabe ao cantor impedir que essas obstruções quebrem a **linha de legato**. A justificativa é pastoral: quem está no último banco — inclusive um visitante que nunca entrou na igreja — precisa **entender o texto cantado**.\n\nO método proposto é o **treino solo-vocálico**: retiram-se todas as consoantes da frase e canta-se apenas a sequência de formas vocálicas (com as **semivogais**), para depois recolocar as consoantes **sem perder a qualidade da articulação** já montada. A abertura das **formas das vogais** é o que **minimiza o impacto das consoantes**. Na análise, consoantes **oclusivas/explosivas** como \"qu\" e \"t\" recebem atenção especial: elevam a parte central da língua e podem agravar **tensões de língua** já existentes — por isso a instrução recorrente de \"pensar na vogal que vem atrás da consoante\".\n\nA aula conecta o trabalho articulatório ao restante do curso: conhecer os **espaços das vogais** ajuda a projetar **notas agudas** (com mais espaço), a direcionar o som nas **graves**, e a executar **passagens de registro** com menos tensão, escolhendo onde usar um **modo de fonação** mais firme ou mais fluido. Por fim, há um recado direto a **contraltos e baixos**: na região grave — mais densa e próxima da fala — é comum mexer pouco a **musculatura facial**, e a linha melódica \"embola\" com facilidade; o treino articulatório é, para esses naipes, ainda mais importante.",
          "notas": "- Aula de **aplicação cumulativa**: pressupõe as aulas de vogais/consoantes e resgata **modos de fonação** e **musculatura facial** estudados antes.\n- Sugestão de prática: o aluno deve repetir o método (tirar consoantes → cantar vogais → recolocar consoantes) em outras frases do próprio repertório, independentemente do naipe.\n- A dificuldade inicial do treino solo-vocálico é normalizada pela instrutora, que ensina o caminho: identificar as vogais palavra por palavra antes de cantar.",
