          "prose": "<p>Nesta aula, o conteúdo técnico acumulado — formação das **vogais** no trato vocal, **modo de articulação**, **ponto de articulação** e **vozeamento** das consoantes — é colocado a serviço de um repertório real da igreja: o hino **\"Vida em abundância\"**. A premissa é clara: quem canta no grupo de louvor tem a missão de **transmitir uma mensagem** (consolo, renovo, salvação), e essa mensagem só chega ao ouvinte — membro ou visitante — se o **texto cantado for inteligível**. Por isso, a **vogal** é tratada como ponto-chave: é ela que sustenta a **dicção**, a **articulação** e, em última instância, a qualidade do texto em meio aos constantes **ajustes fisiológicos e articulatórios** exigidos pela linha melódica.</p>\n<p>Na prática, a instrutora conduz a estrofe passo a passo: ouvir a **introdução instrumental** como sinal para **respirar e montar a forma** antes da entrada; avaliar se a frase \"olha em teu coração só dor\" cabe numa **respiração só** ou pede uma pausa, conforme a realidade de cada grupo; abrir **espaço e mandíbula** na nota aguda final; projetar um som **leve e para frente**, economizando intensidade para não precisar forçar no refrão. Há orientações específicas por naipe — **tenores**, **contraltos** e **baixos** — com atenção especial às vozes graves, onde a articulação pouco limpa \"embola\" o som. O detalhe do **lábio superior elevado** (mostrar os dentes em \"rolam\") exemplifica como a musculatura facial influencia o que acontece dentro do trato vocal, incluindo a posição do **palato**.</p>\n<p>**Nota didática:** a instrutora evita deliberadamente recursos individuais (como vibrato) e não propõe um \"modelo de voz\" a ser imitado — o foco é o **conceito fisiológico e articulatório**, para que cada aluno imprima sua **identidade vocal** e o grupo construa um som de **naipe equilibrado**. Reforce aos alunos que adaptações (respiração extra, oitavação) são legítimas e dependem da realidade de cada igreja e de cada naipe.</p>",
